import React from 'react';

export interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {}

export const Skeleton: React.FC<SkeletonProps> = ({
  className = '',
  ...props
}) => {
  return (
    <div
      className={`animate-pulse rounded-md bg-slate-200 dark:bg-slate-800 ${className}`}
      {...props}
    />
  );
};

import { useAuthStore } from '../../stores/authStore';
import { useUIStore } from '../../stores/uiStore';
import { ROLE_NAV_ITEMS, NavItem } from '../../constants/roles';
import { Link, useLocation } from 'react-router-dom';
import * as Icons from 'lucide-react';

export default function Sidebar() {
  const { user } = useAuthStore();
  const { isSidebarOpen } = useUIStore();
  const location = useLocation();

  if (!user) return null;

  const navItems = ROLE_NAV_ITEMS[user.role] || [];

  const renderIcon = (iconName: string) => {
    const IconComponent = (Icons as any)[iconName];
    return IconComponent ? <IconComponent size={20} /> : <Icons.Circle size={20} />;
  };

  return (
    <aside 
      className={`fixed left-0 top-0 h-full bg-surface-primary border-r border-border-secondary transition-all duration-300 z-[200] flex flex-col`}
      style={{ width: isSidebarOpen ? 'var(--sidebar-width)' : 'var(--sidebar-collapsed-width)' }}
    >
      {/* Brand area */}
      <div className="h-[64px] flex items-center px-4 border-b border-border-secondary shrink-0 overflow-hidden" style={{ height: 'var(--header-height)' }}>
        <div className="w-10 h-10 flex items-center justify-center shrink-0">
          <img src="/logo_transparent.png" alt="Logo" className="w-full h-full object-contain" />
        </div>
        <div className={`ml-3 whitespace-nowrap transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100' : 'opacity-0 hidden'}`}>
          <h2 className="font-bold text-sm text-slate-800 dark:text-slate-100 leading-tight">Camied Behills</h2>
          <p className="text-[10px] text-slate-500 dark:text-slate-400">Int. School</p>
        </div>
      </div>

      {/* Nav links */}
      <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 scrollbar-hide">
        {navItems.map((item: NavItem) => {
          const isActive = location.pathname.startsWith(item.path);

          return (
            <div key={item.path}>
              <Link 
                to={item.path}
                className={`flex items-center px-3 py-2.5 rounded-md transition-all duration-200 group ${
                  isActive 
                    ? 'bg-primary-50 dark:bg-primary-950/40 text-primary-700 dark:text-primary-400 font-medium' 
                    : 'text-secondary hover:bg-surface-tertiary hover:text-primary-600'
                }`}
                title={!isSidebarOpen ? item.label : undefined}
              >
                <div className={`shrink-0 ${isActive ? 'text-primary-600 dark:text-primary-400' : 'text-tertiary group-hover:text-primary-500'}`}>
                  {renderIcon(item.icon)}
                </div>
                <span className={`ml-3 whitespace-nowrap transition-all duration-300 ${isSidebarOpen ? 'opacity-100' : 'opacity-0 hidden'}`}>
                  {item.label}
                </span>

                {item.children && isSidebarOpen && (
                  <div className="ml-auto">
                    <Icons.ChevronDown size={16} className={`transition-transform ${isActive ? 'rotate-180' : ''}`} />
                  </div>
                )}
              </Link>

              {/* Children (Only show if parent active and sidebar open) */}
              {item.children && isActive && isSidebarOpen && (
                <div className="mt-1 ml-4 pl-4 border-l border-border-secondary space-y-1">
                  {item.children.map((child: NavItem) => {
                    const isChildActive = location.pathname === child.path;
                    return (
                      <Link
                        key={child.path}
                        to={child.path}
                        className={`flex items-center px-3 py-2 text-sm rounded-md transition-colors ${
                          isChildActive
                            ? 'text-primary-600 font-medium bg-surface-primary'
                            : 'text-tertiary hover:text-primary-500 hover:bg-surface-tertiary'
                        }`}
                      >
                        {child.label}
                      </Link>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </nav>

      {/* User profile snippet at bottom */}
      <div className={`border-t border-border-secondary p-4 shrink-0 overflow-hidden transition-all duration-300 ${!isSidebarOpen ? 'flex justify-center' : ''}`}>
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-primary-100 text-primary-700 flex-center font-bold shrink-0">
            {user.firstName[0]}{user.lastName[0]}
          </div>
          <div className={`whitespace-nowrap transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100' : 'opacity-0 hidden'}`}>
            <p className="font-semibold text-sm truncate w-32">{user.firstName} {user.lastName}</p>
            <p className="text-xs text-tertiary capitalize">{user.role.replace('_', ' ')}</p>
          </div>
        </div>
      </div>
    </aside>
  );
}

import { useState, useCallback, useMemo } from 'react';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { Assessment, ExamResult, SubjectResult, ReportCard, Subject, GradeValue, GHANA_GRADING_SCALE } from '../../../types/academic';
import { Student } from '../../../types/student';
import { Term, ClassLevel } from '../../../types/common';

export function useAcademics() {
  const assessmentAdapter = useMemo(() => new LocalStorageAdapter<Assessment>('advance_assessments'), []);
  const resultAdapter = useMemo(() => new LocalStorageAdapter<ExamResult>('advance_exam_results'), []);
  const studentAdapter = useMemo(() => new LocalStorageAdapter<Student>('advance_students'), []);

  const [assessments, setAssessments] = useState<Assessment[]>(() => assessmentAdapter.getAll());
  const [results, setResults] = useState<ExamResult[]>(() => resultAdapter.getAll());

  const refreshAssessments = useCallback(() => {
    setAssessments(assessmentAdapter.getAll());
  }, [assessmentAdapter]);

  const refreshResults = useCallback(() => {
    setResults(resultAdapter.getAll());
  }, [resultAdapter]);

  const createAssessment = useCallback((newAssess: Assessment) => {
    assessmentAdapter.create(newAssess);
    refreshAssessments();
  }, [assessmentAdapter, refreshAssessments]);

  const recordExamResult = useCallback((newResult: ExamResult) => {
    const all = resultAdapter.getAll();
    const existing = all.find(
      (r) => r.assessmentId === newResult.assessmentId && r.studentId === newResult.studentId
    );
    if (existing) {
      resultAdapter.update(existing.id, newResult);
    } else {
      resultAdapter.create(newResult);
    }
    refreshResults();
  }, [resultAdapter, refreshResults]);

  // Lookup grade value and remark based on score
  const getGradeFromScore = useCallback((score: number): { grade: GradeValue; remark: string } => {
    const scale = GHANA_GRADING_SCALE.find((s) => score >= s.minScore && score <= s.maxScore);
    return scale ? { grade: scale.grade, remark: scale.remark } : { grade: '9', remark: 'Fail' };
  }, []);

  const getGradebook = useCallback((classLevel: ClassLevel, subject: Subject, _term: Term, _academicYear: string) => {
    const studentsInClass = studentAdapter.getAll().filter((s) => s.classLevel === classLevel && s.status === 'active');
    const classAssessments = assessmentAdapter.getAll().filter(
      (a) => a.classLevel === classLevel && a.subject === subject
    );

    // Find end-of-term assessment
    const examAssess = classAssessments.find((a) => a.type === 'end_of_term');
    // Find class tests
    const testAssessments = classAssessments.filter((a) => a.type === 'class_test');

    const resultsList = resultAdapter.getAll();

    return studentsInClass.map((student) => {
      // Calculate average test score (scaled to 30%)
      const studentTestScores = testAssessments.map((a) => {
        const res = resultsList.find((r) => r.assessmentId === a.id && r.studentId === student.id);
        return res ? (res.score / a.maxScore) * 30 : 0;
      });
      const classWorkScore = studentTestScores.length > 0
        ? Math.round(studentTestScores.reduce((acc, s) => acc + s, 0) / studentTestScores.length * 10) / 10
        : 0;

      // Calculate exam score (scaled to 70%)
      const examRes = examAssess 
        ? resultsList.find((r) => r.assessmentId === examAssess.id && r.studentId === student.id)
        : null;
      const examScore = examRes && examAssess
        ? Math.round((examRes.score / examAssess.maxScore) * 70 * 10) / 10
        : 0;

      const totalScore = Math.round(classWorkScore + examScore);
      const { grade, remark } = getGradeFromScore(totalScore);

      return {
        studentId: student.id,
        studentName: `${student.firstName} ${student.lastName}`,
        classWorkScore,
        examScore,
        totalScore,
        grade,
        remark,
        examRawScore: examRes ? examRes.score : 0,
        examMaxScore: examAssess ? examAssess.maxScore : 100
      };
    }).sort((a, b) => b.totalScore - a.totalScore)
      .map((student, idx, arr) => {
        // Calculate subject position
        let position = idx + 1;
        if (idx > 0 && student.totalScore === arr[idx - 1].totalScore) {
          position = (arr[idx - 1] as any).position; // handle ties
        }
        return {
          ...student,
          position
        };
      });
  }, [studentAdapter, assessmentAdapter, resultAdapter, getGradeFromScore]);

  const generateReportCard = useCallback((studentId: string, term: Term, academicYear: string): ReportCard | null => {
    const student = studentAdapter.getById(studentId);
    if (!student) return null;

    const subjects: Subject[] = [
      'English Language', 'Mathematics', 'Integrated Science', 'Social Studies', 
      'ICT', 'French', 'Ghanaian Language', 'RME'
    ];

    const resultsSummary: SubjectResult[] = [];
    let totalScore = 0;

    subjects.forEach((subj) => {
      const gradebook = getGradebook(student.classLevel, subj, term, academicYear);
      const studentRecord = gradebook.find((r) => r.studentId === studentId);

      if (studentRecord) {
        resultsSummary.push({
          subject: subj,
          classWorkScore: studentRecord.classWorkScore,
          examScore: studentRecord.examScore,
          totalScore: studentRecord.totalScore,
          grade: studentRecord.grade,
          remark: studentRecord.remark,
          positionInSubject: studentRecord.position
        });
        totalScore += studentRecord.totalScore;
      }
    });

    if (resultsSummary.length === 0) return null;

    const averageScore = Math.round((totalScore / resultsSummary.length) * 100) / 100;

    // Calculate overall class positions
    const classStudents = studentAdapter.getAll().filter((s) => s.classLevel === student.classLevel && s.status === 'active');
    const classTotalScores = classStudents.map((s) => {
      let sum = 0;
      subjects.forEach((subj) => {
        const gradebook = getGradebook(student.classLevel, subj, term, academicYear);
        const record = gradebook.find((r) => r.studentId === s.id);
        if (record) sum += record.totalScore;
      });
      return { studentId: s.id, total: sum };
    }).sort((a, b) => b.total - a.total);

    const overallPosition = classTotalScores.findIndex((s) => s.studentId === studentId) + 1;

    // Default comments
    let teacherComment = 'A good performance. Keep it up.';
    if (averageScore >= 80) teacherComment = 'Excellent work. Maintain this standard.';
    else if (averageScore < 50) teacherComment = 'Needs to put in more effort next term.';

    return {
      id: `rep_${studentId}_${term.replace(' ', '')}`,
      studentId,
      studentName: `${student.firstName} ${student.lastName}`,
      classLevel: student.classLevel,
      term,
      academicYear,
      results: resultsSummary,
      totalScore,
      averageScore,
      overallPosition,
      classSize: classStudents.length,
      attendanceSummary: {
        totalDays: 60,
        daysPresent: 58,
        daysAbsent: 2
      },
      teacherComment,
      headTeacherComment: averageScore >= 70 ? 'A very promising result. Outstanding!' : 'Satisfactory progress. Put in more work.',
      nextTermBegins: '2026-09-08',
      dateIssued: new Date().toISOString().split('T')[0]
    };
  }, [studentAdapter, getGradebook]);

  return {
    assessments,
    results,
    createAssessment,
    recordExamResult,
    getGradebook,
    generateReportCard,
    refreshAssessments,
    refreshResults
  };
}

import { useState, useMemo } from 'react';
import { useStudents } from '../../students/hooks/useStudents';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody, CardHeader, CardTitle } from '../../../components/ui/Card';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { EmptyState } from '../../../components/data-display/EmptyState';
import { StatCard } from '../../../components/data-display/StatCard';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { AttendanceRecord } from '../../../types';
import { Users, CheckCircle, Clock, AlertTriangle, Search } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

export default function AcademicAttendancePage() {
  const { students } = useStudents();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedClass, setSelectedClass] = useState('all');
  const [selectedDate, setSelectedDate] = useState(() => new Date().toISOString().split('T')[0]);

  const attendanceAdapter = useMemo(() => new LocalStorageAdapter<AttendanceRecord>('advance_student_attendance'), []);

  const attendanceList = useMemo(() => {
    return attendanceAdapter.getAll();
  }, [attendanceAdapter]);

  // Daily Roster for the selected date
  const dailyRoster = useMemo(() => {
    return students.map(student => {
      // Find today's attendance
      const record = attendanceList.find(a => a.studentId === student.id && a.date === selectedDate);
      return {
        id: student.id,
        studentId: student.studentId,
        name: `${student.firstName} ${student.lastName}`,
        classLevel: student.classLevel,
        status: record ? record.status : 'unrecorded',
        notes: record ? record.notes : ''
      };
    });
  }, [students, attendanceList, selectedDate]);

  // Filtered Daily Roster
  const filteredRoster = useMemo(() => {
    return dailyRoster.filter(row => {
      const matchesSearch = row.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            row.studentId.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesClass = selectedClass === 'all' || row.classLevel === selectedClass;
      return matchesSearch && matchesClass;
    });
  }, [dailyRoster, searchTerm, selectedClass]);

  // Statistics for selected date
  const stats = useMemo(() => {
    const activeStudents = dailyRoster.length;
    const present = dailyRoster.filter(r => r.status === 'present').length;
    const late = dailyRoster.filter(r => r.status === 'late').length;
    const absent = dailyRoster.filter(r => r.status === 'absent').length;
    const excused = dailyRoster.filter(r => r.status === 'excused').length;
    const unrecorded = dailyRoster.filter(r => r.status === 'unrecorded').length;

    const recordedCount = present + late + absent + excused;
    const attendanceRate = recordedCount > 0 ? ((present + late) / recordedCount) * 100 : 100;

    return {
      activeStudents,
      present,
      late,
      absent,
      excused,
      unrecorded,
      attendanceRate: attendanceRate.toFixed(1) + '%'
    };
  }, [dailyRoster]);

  // Class-wise charts data
  const classChartData = useMemo(() => {
    const classData: Record<string, { present: number; total: number }> = {};

    // Group records by class level
    dailyRoster.forEach(r => {
      if (r.status !== 'unrecorded') {
        if (!classData[r.classLevel]) {
          classData[r.classLevel] = { present: 0, total: 0 };
        }
        classData[r.classLevel].total++;
        if (r.status === 'present' || r.status === 'late') {
          classData[r.classLevel].present++;
        }
      }
    });

    return Object.entries(classData).map(([className, data]) => ({
      class: className,
      rate: data.total > 0 ? Math.round((data.present / data.total) * 100) : 100
    }));
  }, [dailyRoster]);

  const columns: Column<any>[] = [
    {
      header: 'Student ID',
      accessorKey: 'studentId',
      cell: (row) => <span className="font-mono text-xs font-semibold">{row.studentId}</span>
    },
    {
      header: 'Student Name',
      accessorKey: 'name',
      cell: (row) => <span className="font-medium text-slate-900 dark:text-white">{row.name}</span>
    },
    {
      header: 'Class Level',
      accessorKey: 'classLevel',
      cell: (row) => <span className="capitalize">{row.classLevel}</span>
    },
    {
      header: 'Status',
      accessorKey: 'status',
      cell: (row) => {
        const variants: Record<string, 'neutral' | 'success' | 'danger' | 'warning' | 'primary'> = {
          present: 'success',
          late: 'warning',
          absent: 'danger',
          excused: 'neutral',
          unrecorded: 'neutral'
        };
        return (
          <Badge variant={variants[row.status] || 'neutral'} className="capitalize">
            {row.status}
          </Badge>
        );
      }
    },
    {
      header: 'Notes / Remarks',
      accessorKey: 'notes',
      cell: (row) => (
        <span className="text-xs text-slate-500 dark:text-slate-400">
          {row.notes || <span className="italic text-slate-300 dark:text-slate-600">None</span>}
        </span>
      )
    }
  ];

  return (
    <PageWrapper
      title="Student Attendance Center"
      subtitle="Monitor school-wide student attendance, evaluate class-wise check-ins, and inspect absentees."
      breadcrumbs={[
        { label: 'Academic Reports', path: '/academics' },
        { label: 'Attendance logs' }
      ]}
    >
      {/* Date & Filter Toolbar */}
      <div className="flex flex-col sm:flex-row gap-4 items-end justify-between bg-white dark:bg-slate-900 p-4 rounded-xl border border-border-secondary shadow-sm mb-6">
        <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
          <Input
            label="Log Date"
            type="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            className="w-full sm:w-48"
          />
          <Select
            label="Filter Class"
            value={selectedClass}
            onChange={(e) => setSelectedClass(e.target.value)}
            options={[
              { value: 'all', label: 'All Classes' },
              { value: 'JHS 1', label: 'JHS Level 1' },
              { value: 'JHS 2', label: 'JHS Level 2' },
              { value: 'JHS 3', label: 'JHS Level 3' },
              { value: 'Primary 1', label: 'Primary 1' },
              { value: 'Primary 2', label: 'Primary 2' }
            ]}
            className="w-full sm:w-40"
          />
        </div>

        <div className="relative w-full sm:w-64">
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search by student ID or name..."
            className="w-full pl-9"
          />
          <Search className="absolute left-3 top-3.5 h-4 w-4 text-slate-400" />
        </div>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard
          title="Attendance Rate"
          value={stats.attendanceRate}
          icon={<CheckCircle className="text-success-500" />}
          className="bg-success-50/10"
        />
        <StatCard
          title="Present Today"
          value={stats.present + stats.late}
          icon={<Users className="text-primary-500" />}
        />
        <StatCard
          title="Absentees"
          value={stats.absent}
          icon={<AlertTriangle className="text-danger-500" />}
        />
        <StatCard
          title="Unrecorded"
          value={stats.unrecorded}
          icon={<Clock className="text-warning-500" />}
        />
      </div>

      {/* Split grid for list and charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Roster list */}
        <div className="lg:col-span-2">
          <Card className="h-full">
            <CardHeader>
              <CardTitle>Daily Attendance Roster</CardTitle>
            </CardHeader>
            <CardBody className="p-0">
              {filteredRoster.length > 0 ? (
                <DataTable data={filteredRoster} columns={columns} />
              ) : (
                <div className="p-6">
                  <EmptyState
                    title="No Records Found"
                    description="No student attendance records matched your filter criteria."
                  />
                </div>
              )}
            </CardBody>
          </Card>
        </div>

        {/* Charts */}
        <div className="col-span-1">
          <Card className="h-full">
            <CardHeader>
              <CardTitle>Class Attendance %</CardTitle>
            </CardHeader>
            <CardBody className="flex flex-col justify-center items-center h-[300px]">
              {classChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={classChartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-border-secondary)" />
                    <XAxis dataKey="class" tickLine={false} tick={{ fontSize: 10 }} />
                    <YAxis domain={[0, 100]} unit="%" tickLine={false} tick={{ fontSize: 10 }} />
                    <Tooltip cursor={{ fill: 'transparent' }} formatter={(val) => [`${val}%`, 'Attendance Rate']} />
                    <Bar dataKey="rate" fill="var(--color-primary-500)" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div className="text-center text-slate-400 text-xs py-12">No class stats recorded for this date.</div>
              )}
            </CardBody>
          </Card>
        </div>
      </div>
    </PageWrapper>
  );
}

import React, { useState } from 'react';
import { useAdmin } from '../hooks/useAdmin';
import { useAuthStore } from '../../../stores/authStore';
import { useNotificationStore } from '../../../stores/notificationStore';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { Tabs } from '../../../components/ui/Tabs';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { LeaveRequest } from '../../../types/staff';
import { Expense } from '../../../types/finance';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { CalendarOff, Receipt, Check, X } from 'lucide-react';

export default function ApprovalsPage() {
  const { 
    leaveRequests, 
    expenses, 
    approveLeave, 
    rejectLeave, 
    approveExpense, 
    rejectExpense 
  } = useAdmin();
  const { user } = useAuthStore();
  const addToast = useNotificationStore((state) => state.addToast);

  const [activeTab, setActiveTab] = useState('leave');

  // Rejection modal state
  const [rejectingItem, setRejectingItem] = useState<{ id: string; type: 'leave' | 'expense' } | null>(null);
  const [rejectionRemarks, setRejectionRemarks] = useState('');

  const handleApproveLeave = (id: string, _staffId: string) => {
    if (!user) return;
    approveLeave(id, user.id, user.id, `${user.firstName} ${user.lastName}`);
    addToast({ type: 'success', message: 'Leave request approved successfully!' });
  };

  const handleApproveExpense = (id: string) => {
    if (!user) return;
    approveExpense(id, user.id, `${user.firstName} ${user.lastName}`);
    addToast({ type: 'success', message: 'Expense request approved and recorded.' });
  };

  const handleOpenRejectModal = (id: string, type: 'leave' | 'expense') => {
    setRejectingItem({ id, type });
    setRejectionRemarks('');
  };

  const handleConfirmReject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !rejectingItem) return;

    if (!rejectionRemarks.trim()) {
      addToast({ type: 'error', message: 'Please specify the rejection reason.' });
      return;
    }

    if (rejectingItem.type === 'leave') {
      rejectLeave(rejectingItem.id, user.id, rejectionRemarks, user.id, `${user.firstName} ${user.lastName}`);
      addToast({ type: 'success', message: 'Leave request rejected.' });
    } else {
      rejectExpense(rejectingItem.id, user.id, `${user.firstName} ${user.lastName}`);
      addToast({ type: 'success', message: 'Expense request rejected.' });
    }
    setRejectingItem(null);
  };

  const pendingLeaves = leaveRequests.filter((r) => r.status === 'pending');
  const pendingExpenses = expenses.filter((e) => e.status === 'pending');

  const leaveColumns: Column<LeaveRequest>[] = [
    {
      header: 'Staff ID',
      accessorKey: 'staffId',
      sortable: true
