        {activeTab === 'expense' && (
          <Card className="animate-fade-in">
            <CardBody>
              <DataTable 
                data={pendingExpenses} 
                columns={expenseColumns} 
                searchKey="description" 
                searchPlaceholder="Search by description..." 
