import { useState } from 'react';
import { useAdmin, SchoolSettings } from '../hooks/useAdmin';
import { useAuthStore } from '../../../stores/authStore';
import { useNotificationStore } from '../../../stores/notificationStore';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Tabs } from '../../../components/ui/Tabs';
import { ClassLevel, Term, CLASS_LEVELS, TERMS } from '../../../types/common';
import { Building, Calendar, LayoutGrid, CheckCircle } from 'lucide-react';

export default function SettingsPage() {
  const { settings, saveSettings } = useAdmin();
  const { user } = useAuthStore();
  const addToast = useNotificationStore((state) => state.addToast);

  const [activeTab, setActiveTab] = useState('school');

  // State for forms
  const [schoolName, setSchoolName] = useState(settings.schoolName);
  const [academicYear, setAcademicYear] = useState(settings.academicYear);
  const [activeTerm, setActiveTerm] = useState<Term>(settings.activeTerm);
  const [classLevels, setClassLevels] = useState<Record<ClassLevel, boolean>>(settings.classLevels);

  const [schoolMotto, setSchoolMotto] = useState('Scientia Potestas Est');
  const [schoolAddress, setSchoolAddress] = useState('Camied Hills, Accra, Ghana');

  const handleToggleClass = (lvl: ClassLevel) => {
    setClassLevels((prev) => ({
      ...prev,
      [lvl]: !prev[lvl]
    }));
  };

  const handleSave = () => {
    if (!user) return;
    try {
      const updated: SchoolSettings = {
        id: settings.id || 'global',
        schoolName,
        academicYear,
        activeTerm,
        classLevels
      };
      saveSettings(updated, user.id, `${user.firstName} ${user.lastName}`);
      addToast({ type: 'success', message: 'Global settings updated successfully!' });
    } catch (err: any) {
      addToast({ type: 'error', message: err.message || 'Failed to save settings.' });
    }
  };

  const tabs = [
    { id: 'school', label: 'School Metadata', icon: <Building size={16} /> },
    { id: 'academic', label: 'Academic Term', icon: <Calendar size={16} /> },
    { id: 'classes', label: 'Class Configuration', icon: <LayoutGrid size={16} /> }
  ];

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Admin Panel' },
    { label: 'Settings' }
  ];

  return (
    <PageWrapper 
      title="Global School Settings" 
      subtitle="Manage institutional configuration parameters, active terms, and active academic class pipelines."
      breadcrumbs={breadcrumbs}
      action={
        <Button variant="primary" onClick={handleSave} leftIcon={<CheckCircle size={18} />}>
          Save Settings
        </Button>
      }
    >
      <div className="space-y-6">
        <Tabs tabs={tabs} activeTab={activeTab} onChange={setActiveTab} variant="pill" />

        {activeTab === 'school' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fade-in">
            <div className="lg:col-span-2 space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>School Information</CardTitle>
                </CardHeader>
                <CardBody className="space-y-4">
                  <Input
                    label="School Name *"
                    value={schoolName}
                    onChange={(e) => setSchoolName(e.target.value)}
                    required
                  />
                  <Input
                    label="School Motto"
                    value={schoolMotto}
                    onChange={(e) => setSchoolMotto(e.target.value)}
                  />
                  <Input
                    label="Address"
                    value={schoolAddress}
                    onChange={(e) => setSchoolAddress(e.target.value)}
                  />
                </CardBody>
              </Card>
            </div>

            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>School Crest / Logo</CardTitle>
                </CardHeader>
                <CardBody className="flex flex-col items-center justify-center py-6 text-center">
                  <div className="w-32 h-32 flex items-center justify-center mb-4 shrink-0">
                    <img src="/logo_transparent.png" alt="School crest preview" className="w-full h-full object-contain" />
                  </div>
                  <h4 className="font-semibold text-slate-900 dark:text-white text-sm">Camied Behills Logo</h4>
                  <p className="text-xs text-slate-500 mt-1">Stored securely in the application assets</p>
                </CardBody>
              </Card>
            </div>
          </div>
        )}

        {activeTab === 'academic' && (
          <div className="max-w-2xl animate-fade-in">
            <Card>
              <CardHeader>
                <CardTitle>Active Term & Academic Calendar</CardTitle>
              </CardHeader>
              <CardBody className="space-y-6">
                <Select
                  label="Active Term *"
                  value={activeTerm}
                  onChange={(e) => setActiveTerm(e.target.value as Term)}
                  options={TERMS.map((t) => ({ value: t, label: t }))}
                />
                <Input
                  label="Active Academic Year *"
                  placeholder="e.g. 2025/2026"
                  value={academicYear}
                  onChange={(e) => setAcademicYear(e.target.value)}
                  required
                />
                <div className="p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-900/50 rounded-xl text-amber-800 dark:text-amber-300 text-sm">
                  <strong>Important Notice:</strong> Modifying the active academic term affects invoicing, fee schedules, exam records, and student report card calculations globally across the portal.
                </div>
              </CardBody>
            </Card>
          </div>
        )}

        {activeTab === 'classes' && (
          <div className="animate-fade-in">
            <Card>
              <CardHeader>
                <CardTitle>Institutional Class Channels</CardTitle>
              </CardHeader>
              <CardBody>
                <p className="text-sm text-slate-500 mb-6">
                  Select which class levels are active in the system. Disabling a level hides it from enrollment portals and grading pipelines without deleting historical student transcripts.
                </p>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
                  {CLASS_LEVELS.map((lvl) => {
                    const isActive = classLevels[lvl];
                    return (
                      <button
                        key={lvl}
                        type="button"
                        onClick={() => handleToggleClass(lvl)}
                        className={`p-4 rounded-xl border text-center font-medium transition-all duration-200 ${
                          isActive
                            ? 'border-primary-500 bg-primary-50/30 dark:bg-primary-950/10 text-primary-700 dark:text-primary-300 shadow-sm'
                            : 'border-slate-200 dark:border-slate-800 text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800/30'
                        }`}
                      >
                        <div className="text-sm font-semibold">{lvl}</div>
                        <div className="text-[10px] mt-1 uppercase tracking-wider font-bold">
                          {isActive ? 'Active' : 'Disabled'}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </CardBody>
            </Card>
          </div>
        )}
      </div>
    </PageWrapper>
  );
}

import React, { useState } from 'react';
import { useAdmin } from '../hooks/useAdmin';
import { useAuthStore } from '../../../stores/authStore';
import { useNotificationStore } from '../../../stores/notificationStore';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { User, UserRole, Permission } from '../../../types/auth';
import { UserPlus, Edit2, ShieldAlert, CheckCircle, XCircle } from 'lucide-react';

const ROLE_OPTIONS = [
  { value: 'super_admin', label: 'Super Admin' },
  { value: 'admin', label: 'Admin' },
  { value: 'teacher', label: 'Teacher' },
  { value: 'parent', label: 'Parent' },
  { value: 'student', label: 'Student' }
];

const ALL_PERMISSIONS: { value: Permission; label: string }[] = [
  { value: 'manage_users', label: 'Manage Users' },
  { value: 'manage_students', label: 'Manage Students' },
  { value: 'manage_staff', label: 'Manage Staff' },
  { value: 'manage_fees', label: 'Manage Fee Modules' },
  { value: 'manage_academics', label: 'Manage Academic Data' },
  { value: 'view_reports', label: 'View Financial/Academic Reports' },
  { value: 'view_own_student', label: 'View Own Student Profile' },
  { value: 'view_own_child', label: 'View Own Child Details' },
  { value: 'enter_grades', label: 'Enter Academic Grades' },
  { value: 'pay_fees', label: 'Pay Student Fees' }
];

const DEFAULT_ROLE_PERMISSIONS: Record<UserRole, Permission[]> = {
  super_admin: ['manage_users', 'manage_students', 'manage_staff', 'manage_fees', 'manage_academics', 'view_reports'],
  admin: ['manage_students', 'manage_staff', 'manage_fees', 'manage_academics', 'view_reports'],
  teacher: ['view_own_student', 'enter_grades'],
  parent: ['view_own_child', 'pay_fees'],
  student: ['view_own_student']
};

export default function UserManagementPage() {
  const { users, createUser, updateUser, toggleUserStatus } = useAdmin();
  const { user: currentUser } = useAuthStore();
  const addToast = useNotificationStore((state) => state.addToast);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Form fields
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>('teacher');
  const [selectedPermissions, setSelectedPermissions] = useState<Permission[]>([]);

  const handleOpenCreateModal = () => {
    setEditingUser(null);
    setFirstName('');
    setLastName('');
    setEmail('');
    setRole('teacher');
    setSelectedPermissions(DEFAULT_ROLE_PERMISSIONS['teacher']);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (user: User) => {
    setEditingUser(user);
    setFirstName(user.firstName);
    setLastName(user.lastName);
    setEmail(user.email);
    setRole(user.role);
    setSelectedPermissions(user.permissions);
    setIsModalOpen(true);
  };

  const handleRoleChange = (selectedRole: UserRole) => {
    setRole(selectedRole);
    setSelectedPermissions(DEFAULT_ROLE_PERMISSIONS[selectedRole]);
  };

  const handleTogglePermission = (perm: Permission) => {
    setSelectedPermissions((prev) => 
      prev.includes(perm) ? prev.filter((p) => p !== perm) : [...prev, perm]
    );
  };

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    if (!firstName || !lastName || !email) {
      addToast({ type: 'error', message: 'Please fill in all required fields.' });
      return;
    }

    try {
      if (editingUser) {
        // Edit User
        const updated: User = {
          ...editingUser,
          firstName,
          lastName,
          email,
          role,
          permissions: selectedPermissions
        };
        updateUser(updated, currentUser.id, `${currentUser.firstName} ${currentUser.lastName}`);
        addToast({ type: 'success', message: 'User updated successfully!' });
      } else {
        // Create User
        const newUser: Omit<User, 'createdAt'> = {
          id: `usr_${Math.random().toString(36).substring(7)}`,
          firstName,
          lastName,
          email,
          role,
          status: 'active',
          permissions: selectedPermissions
        };
        createUser(newUser, currentUser.id, `${currentUser.firstName} ${currentUser.lastName}`);
        addToast({ type: 'success', message: 'User created successfully!' });
      }
      setIsModalOpen(false);
    } catch (err: any) {
      addToast({ type: 'error', message: err.message || 'An error occurred while saving.' });
    }
  };

  const handleToggleStatus = (user: User) => {
    if (!currentUser) return;
    if (user.id === currentUser.id) {
      addToast({ type: 'error', message: 'You cannot deactivate your own account!' });
      return;
    }
    toggleUserStatus(user.id, user.status, currentUser.id, `${currentUser.firstName} ${currentUser.lastName}`);
    addToast({ 
      type: 'success', 
      message: `Account for ${user.firstName} ${user.lastName} has been ${user.status === 'active' ? 'deactivated' : 'activated'}.` 
    });
  };

  const columns: Column<User>[] = [
    {
      header: 'Name',
      accessorKey: 'firstName',
      sortable: true,
      cell: (item) => (
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-primary-100 dark:bg-primary-950/30 text-primary-700 dark:text-primary-300 flex-center font-bold text-sm">
            {item.firstName[0]}{item.lastName[0]}
          </div>
          <div>
            <div className="font-semibold text-slate-900 dark:text-white">{item.firstName} {item.lastName}</div>
            <div className="text-xs text-slate-500">{item.email}</div>
          </div>
        </div>
      )
    },
    {
      header: 'Role',
      accessorKey: 'role',
      sortable: true,
      cell: (item) => {
        const roleColors: Record<UserRole, 'primary' | 'danger' | 'success' | 'warning' | 'neutral'> = {
          super_admin: 'danger',
          admin: 'primary',
          teacher: 'primary',
          parent: 'success',
          student: 'warning'
        };
        return (
          <Badge variant={roleColors[item.role] || 'neutral'} className="capitalize">
            {item.role.replace('_', ' ')}
          </Badge>
        );
      }
    },
    {
      header: 'Status',
      accessorKey: 'status',
      sortable: true,
      cell: (item) => (
        <Badge variant={item.status === 'active' ? 'success' : 'danger'}>
          {item.status}
        </Badge>
      )
    },
    {
      header: 'Created At',
      accessorKey: 'createdAt',
      sortable: true,
      cell: (item) => new Date(item.createdAt).toLocaleDateString('en-GB')
    },
    {
      header: 'Actions',
      accessorKey: 'id',
      cell: (item) => (
        <div className="flex gap-2">
          <Button variant="ghost" size="icon" onClick={() => handleOpenEditModal(item)} title="Edit User">
            <Edit2 size={16} />
          </Button>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={() => handleToggleStatus(item)} 
            className={item.status === 'active' ? 'text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/20' : 'text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950/20'}
            title={item.status === 'active' ? 'Deactivate Account' : 'Activate Account'}
          >
            {item.status === 'active' ? <XCircle size={16} /> : <CheckCircle size={16} />}
          </Button>
        </div>
      )
    }
  ];

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Admin Panel' },
    { label: 'Users' }
  ];

  return (
    <PageWrapper 
      title="User Accounts Management" 
      subtitle="Configure system login credentials, assign institutional roles, and audit security permissions."
      breadcrumbs={breadcrumbs}
      action={
        <Button variant="primary" onClick={handleOpenCreateModal} leftIcon={<UserPlus size={18} />}>
          Add New User
        </Button>
      }
    >
      <Card>
        <CardBody>
          <DataTable 
            data={users} 
            columns={columns} 
            searchKey="email" 
            searchPlaceholder="Search user accounts by email..." 
            pageSize={10} 
          />
        </CardBody>
      </Card>

      {/* Create/Edit User Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title={editingUser ? 'Edit User Credentials & Roles' : 'Register New User Account'}
        size="lg"
      >
        <form onSubmit={handleSaveUser} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input
              label="First Name *"
              placeholder="e.g. Kwame"
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
              required
            />
            <Input
              label="Last Name *"
              placeholder="e.g. Asante"
              value={lastName}
              onChange={(e) => setLastName(e.target.value)}
              required
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input
              label="Email Address *"
              type="email"
              placeholder="e.g. user@camiedbehills.edu.gh"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              disabled={!!editingUser} // Email acts as login identifier
            />
            <Select
              label="Institutional Role *"
              value={role}
              onChange={(e) => handleRoleChange(e.target.value as UserRole)}
              options={ROLE_OPTIONS}
            />
          </div>

          {/* Granular Permissions Mapping */}
          <div className="border border-slate-200 dark:border-slate-800 rounded-xl p-4 bg-slate-50/50 dark:bg-slate-800/10">
            <div className="flex items-center gap-2 mb-3">
              <ShieldAlert className="text-amber-500 h-5 w-5" />
              <h4 className="font-semibold text-slate-900 dark:text-white text-sm font-heading">
                Granular Security Permissions
              </h4>
            </div>
            <p className="text-xs text-slate-500 mb-4">
              Permissions are initialized with default settings based on the selected role, but can be customized for this specific user.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {ALL_PERMISSIONS.map((perm) => (
                <label 
                  key={perm.value} 
                  className={`flex items-start gap-3 p-3 rounded-lg border text-sm cursor-pointer transition-all duration-200 ${
                    selectedPermissions.includes(perm.value)
                      ? 'border-primary-500 bg-primary-50/30 dark:bg-primary-950/10 text-primary-700 dark:text-primary-300'
                      : 'border-slate-200 dark:border-slate-800 hover:bg-white dark:hover:bg-slate-800/30'
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={selectedPermissions.includes(perm.value)}
                    onChange={() => handleTogglePermission(perm.value)}
                    className="mt-0.5 rounded text-primary-600 focus:ring-primary-500"
                  />
                  <div>
                    <span className="font-medium">{perm.label}</span>
                  </div>
                </label>
              ))}
            </div>
          </div>

          <div className="flex justify-end gap-3 border-t border-slate-200 dark:border-slate-800 pt-4">
            <Button variant="secondary" type="button" onClick={() => setIsModalOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" type="submit">
              {editingUser ? 'Save Changes' : 'Create Account'}
            </Button>
          </div>
        </form>
      </Modal>
    </PageWrapper>
  );
}

import { useMemo } from 'react';
import { useCanteen } from '../hooks/useCanteen';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { StatCard } from '../../../components/data-display/StatCard';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { UtensilsCrossed, TrendingUp, ShoppingBag, PieChart } from 'lucide-react';

export default function CanteenDashboardPage() {
  const { sales, menuItems, canteenStats } = useCanteen();

  // Prepare chart data by menu item categories
  const chartData = useMemo(() => {
    const summary: Record<string, number> = { breakfast: 0, lunch: 0, snack: 0, drink: 0 };
    sales.forEach((s) => {
      const match = menuItems.find((m) => m.id === s.menuItemId);
      if (match) {
        summary[match.category] = (summary[match.category] || 0) + s.totalPrice;
      }
    });

    return [
      { category: 'Breakfast', revenue: summary.breakfast },
      { category: 'Lunch', revenue: summary.lunch },
      { category: 'Snacks', revenue: summary.snack },
      { category: 'Drinks', revenue: summary.drink }
    ];
  }, [sales, menuItems]);

  const columns: Column<any>[] = [
    {
      header: 'Receipt ID',
      accessorKey: 'id',
      sortable: true,
      cell: (item: any) => <span className="font-mono text-xs">{item.id}</span>
    },
    {
      header: 'Meal Ordered',
      accessorKey: 'menuItemId',
      sortable: true,
      cell: (item: any) => {
        const dish = menuItems.find((m) => m.id === item.menuItemId);
        return <span>{dish ? dish.name : 'Unknown Meal'}</span>;
      }
    },
    {
      header: 'Quantity',
      accessorKey: 'quantity',
      sortable: true
    },
    {
      header: 'Total Price',
      accessorKey: 'totalPrice',
      sortable: true,
      cell: (item: any) => `${CURRENCY_SYMBOL}${item.totalPrice.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`
    },
    {
      header: 'Method',
      accessorKey: 'paymentMethod',
      sortable: true,
      cell: (item: any) => (
        <Badge variant={item.paymentMethod === 'prepaid' ? 'success' : 'primary'} className="capitalize">
          {item.paymentMethod}
        </Badge>
      )
    },
    {
      header: 'Date & Time',
      accessorKey: 'date',
      cell: (item: any) => new Date(item.date).toLocaleString('en-GB')
    }
  ];

  const breadcrumbs = [
    { label: 'Canteen Management' },
    { label: 'Dashboard' }
  ];

  return (
    <PageWrapper
      title="Canteen Dashboard"
      subtitle="Examine daily food sales, record cash/prepaid logs, and track popular dish listings."
      breadcrumbs={breadcrumbs}
    >
      <div className="space-y-6">
        {/* KPI stat cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard
            title="Total Cafeteria Revenue"
            value={`${CURRENCY_SYMBOL}${canteenStats.totalRevenue.toLocaleString()}`}
            icon={<TrendingUp className="text-emerald-500" />}
            description="Sum of all cash & prepaid order values"
          />
          <StatCard
            title="Meals Served Today"
            value={`${canteenStats.totalOrders} Meals`}
            icon={<ShoppingBag className="text-indigo-500" />}
            description="Unique POS meal tickets logged"
          />
          <StatCard
            title="Top Selling Dish"
            value={canteenStats.topItem}
            icon={<UtensilsCrossed className="text-amber-500" />}
            description={`With ${canteenStats.maxQty} units ordered today`}
          />
        </div>

        {/* Chart and Recent sales */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Revenue Chart */}
          <Card className="lg:col-span-1">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <PieChart className="text-primary-500" size={18} />
                Revenue by Food Category
              </CardTitle>
            </CardHeader>
            <CardBody>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" className="stroke-slate-200 dark:stroke-slate-800" />
                    <XAxis dataKey="category" className="text-[10px] text-slate-500" />
                    <YAxis className="text-[10px] text-slate-500" />
                    <Tooltip formatter={(value) => `${CURRENCY_SYMBOL}${value}`} />
                    <Bar dataKey="revenue" fill="var(--color-primary-500)" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </CardBody>
          </Card>

          {/* Sales List */}
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <ShoppingBag className="text-indigo-500" size={18} />
                Recent Sales Transactions
              </CardTitle>
            </CardHeader>
            <CardBody>
              <DataTable
                columns={columns}
                data={sales}
                searchPlaceholder="Search sales by receipt ID..."
                searchKey="id"
              />
            </CardBody>
          </Card>
        </div>
      </div>
    </PageWrapper>
  );
}

import { useState } from 'react';
import { useCanteen } from '../hooks/useCanteen';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { useNotificationStore } from '../../../stores/notificationStore';
import { Plus, Edit2 } from 'lucide-react';

export default function MenuPage() {
  const { menuItems, addMenuItem, updateMenuItem } = useCanteen();
  const addToast = useNotificationStore((state) => state.addToast);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);

  // Form state
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState<'breakfast' | 'lunch' | 'snack' | 'drink'>('lunch');
  const [isAvailable, setIsAvailable] = useState(true);

  const handleOpenAddModal = () => {
    setEditingItem(null);
    setName('');
    setDescription('');
    setPrice('');
    setCategory('lunch');
    setIsAvailable(true);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (item: any) => {
    setEditingItem(item);
    setName(item.name);
    setDescription(item.description);
    setPrice(String(item.price));
    setCategory(item.category);
    setIsAvailable(item.isAvailable);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !price) {
      addToast({ type: 'error', message: 'Please complete all required fields.' });
      return;
    }

    const itemPrice = Number(price) || 0;

    if (editingItem) {
      updateMenuItem(editingItem.id, {
        name,
        description,
        price: itemPrice,
        category,
        isAvailable
      });
      addToast({ type: 'success', message: `Menu item "${name}" updated successfully.` });
    } else {
      addMenuItem({
        name,
        description,
        price: itemPrice,
        category,
        isAvailable
      });
      addToast({ type: 'success', message: `Menu item "${name}" added to canteen.` });
    }

    setIsModalOpen(false);
  };

  const handleToggleAvailability = (id: string, currentVal: boolean, name: string) => {
    updateMenuItem(id, { isAvailable: !currentVal });
    addToast({
      type: 'success',
      message: `"${name}" is now marked as ${!currentVal ? 'Available' : 'Unavailable'}`
    });
  };

  const breadcrumbs = [
    { label: 'Canteen Management', path: '/canteen' },
    { label: 'Menu Setup' }
  ];

  return (
    <PageWrapper
      title="Menu Setup"
      subtitle="Manage kitchen meal offerings, categories, prices, and inventory availability."
      breadcrumbs={breadcrumbs}
      action={
        <Button
          variant="primary"
          leftIcon={<Plus size={16} />}
          onClick={handleOpenAddModal}
        >
          Add Menu Item
        </Button>
      }
    >
      <div className="space-y-6">
        {/* Menu Items Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {menuItems.map((item) => (
            <Card key={item.id} className="relative overflow-hidden flex flex-col justify-between">
              <div>
                <div className="h-2 bg-gradient-to-r from-primary-500 to-indigo-600 shrink-0" />
                <CardHeader className="pb-2">
                  <div className="flex justify-between items-start gap-2">
                    <CardTitle className="text-sm font-bold text-slate-800 dark:text-white">{item.name}</CardTitle>
                    <Badge variant={item.category === 'lunch' ? 'success' : item.category === 'breakfast' ? 'warning' : 'primary'} className="capitalize">
                      {item.category}
                    </Badge>
                  </div>
                </CardHeader>
                <CardBody className="py-2 space-y-2">
                  <p className="text-xs text-slate-500 font-light leading-relaxed min-h-[40px]">{item.description}</p>
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-slate-400">Price tag:</span>
                    <span className="font-extrabold text-primary-600 text-sm">{CURRENCY_SYMBOL}{item.price.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-slate-400">Stock Status:</span>
                    <Badge variant={item.isAvailable ? 'success' : 'danger'}>
                      {item.isAvailable ? 'In Stock' : 'Out of Stock'}
                    </Badge>
                  </div>
                </CardBody>
              </div>

              <div className="p-4 bg-slate-50 dark:bg-slate-900 border-t border-border-secondary flex justify-between gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleToggleAvailability(item.id, item.isAvailable, item.name)}
                  className="text-[10px] h-7 px-2"
                >
                  {item.isAvailable ? 'Set Out of Stock' : 'Set Available'}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  leftIcon={<Edit2 size={12} />}
                  onClick={() => handleOpenEditModal(item)}
                  className="text-[10px] h-7 px-2"
                >
                  Edit Item
                </Button>
              </div>
            </Card>
          ))}
        </div>

        {/* Modal form */}
        <Modal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          title={editingItem ? 'Edit Canteen Item' : 'Add New Canteen Item'}
          size="md"
        >
          <form onSubmit={handleSubmit} className="space-y-4">
            <Input
              label="Dish / Meal Name"
              placeholder="e.g. Red Red with Plantain"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
            <Input
              label="Description"
              placeholder="Detail ingredients or size..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
            <div className="grid grid-cols-2 gap-4">
              <Input
                label={`Price (${CURRENCY_SYMBOL})`}
                type="number"
                step="0.01"
                placeholder="0.00"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                required
              />
              <Select
                label="Food Category"
                value={category}
                onChange={(e) => setCategory(e.target.value as any)}
                options={[
                  { value: 'breakfast', label: 'Breakfast' },
                  { value: 'lunch', label: 'Lunch / Entrees' },
                  { value: 'snack', label: 'Snacks / Bites' },
                  { value: 'drink', label: 'Drinks / Beverages' }
                ]}
              />
            </div>

            <div className="flex items-center gap-2 pt-2">
              <input
                id="isAvailable"
                type="checkbox"
                checked={isAvailable}
                onChange={(e) => setIsAvailable(e.target.checked)}
                className="w-4 h-4 rounded text-primary-600 focus:ring-primary-500 border-border-secondary"
              />
              <label htmlFor="isAvailable" className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                Mark as currently available / in stock
              </label>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-border-secondary">
              <Button
                variant="outline"
                onClick={() => setIsModalOpen(false)}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="primary"
              >
                {editingItem ? 'Save Updates' : 'Add to Canteen'}
              </Button>
            </div>
          </form>
        </Modal>
      </div>
    </PageWrapper>
  );
}

import { useState, useMemo } from 'react';
import { useCanteen } from '../hooks/useCanteen';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { useNotificationStore } from '../../../stores/notificationStore';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { Student } from '../../../types/student';
import { ShoppingCart, Plus, Minus, Trash2, Printer } from 'lucide-react';
import { Modal } from '../../../components/ui/Modal';

export default function SalesPage() {
  const { menuItems, recordSale } = useCanteen();
  const addToast = useNotificationStore((state) => state.addToast);

  const studentsList = useMemo(() => {
    return new LocalStorageAdapter<Student>('advance_students').getAll();
  }, []);

  const [activeCategory, setActiveCategory] = useState<string>('all');

  // POS Cart State
  const [cart, setCart] = useState<{ id: string; name: string; price: number; quantity: number }[]>([]);
  const [selectedStudentId, setSelectedStudentId] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'prepaid'>('cash');

  // Checkout Modal/Receipt State
  const [receipt, setReceipt] = useState<any>(null);

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'all') return menuItems.filter(i => i.isAvailable);
    return menuItems.filter(i => i.category === activeCategory && i.isAvailable);
  }, [menuItems, activeCategory]);

  const addToCart = (item: any) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === item.id);
      if (existing) {
        return prev.map((i) => (i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i));
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart((prev) => {
      return prev
        .map((i) => (i.id === itemId ? { ...i, quantity: Math.max(0, i.quantity + delta) } : i))
        .filter((i) => i.quantity > 0);
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart((prev) => prev.filter((i) => i.id !== itemId));
  };

  const cartTotal = useMemo(() => {
    return cart.reduce((acc, i) => acc + i.price * i.quantity, 0);
  }, [cart]);

  const handleCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) {
      addToast({ type: 'error', message: 'Cart is empty. Please add items.' });
      return;
    }

    if (paymentMethod === 'prepaid' && !selectedStudentId) {
      addToast({ type: 'error', message: 'Please select a student for prepaid checkout.' });
      return;
    }

    try {
      let buyerName = 'Walk-in Cash Customer';
      if (selectedStudentId) {
        const stud = studentsList.find((s: Student) => s.id === selectedStudentId);
        if (stud) {
          buyerName = `${stud.firstName} ${stud.lastName} (${stud.classLevel})`;
        }
      }

      // Record sales for all items
      cart.forEach((cartItem) => {
        recordSale(selectedStudentId || 'walk_in', cartItem.id, cartItem.quantity, paymentMethod);
      });

      // Prepare receipt
      setReceipt({
        id: `RCP-POS-${Math.floor(100000 + Math.random() * 900000)}`,
        buyerName,
        paymentMethod,
        items: [...cart],
        total: cartTotal,
        date: new Date().toISOString()
      });

      addToast({ type: 'success', message: 'Transaction recorded successfully!' });
      setCart([]);
      setSelectedStudentId('');
    } catch (err: any) {
      addToast({ type: 'error', message: err.message || 'Checkout failed.' });
    }
  };

  const studentOptions = useMemo(() => {
    return studentsList.map((s: Student) => ({
      value: s.id,
      label: `${s.firstName} ${s.lastName} (${s.classLevel} - ID: ${s.studentId})`
    }));
  }, [studentsList]);

  const breadcrumbs = [
    { label: 'Canteen Management', path: '/canteen' },
    { label: 'POS Terminal' }
  ];

  return (
    <PageWrapper
      title="POS Terminal Sales"
      subtitle="Click items to construct a sales ticket, select a buyer, and record canteen revenues."
      breadcrumbs={breadcrumbs}
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Columns - Menu items & Categories */}
        <div className="lg:col-span-2 space-y-6">
          {/* Categories Tab */}
          <div className="flex gap-2 flex-wrap border-b border-border-secondary pb-4">
            {['all', 'breakfast', 'lunch', 'snack', 'drink'].map((cat) => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-2 text-xs font-semibold rounded-lg transition-all capitalize ${
                  activeCategory === cat
                    ? 'bg-primary-600 text-white shadow-md'
                    : 'bg-white hover:bg-slate-100 border border-border-secondary text-slate-700 dark:bg-slate-900 dark:hover:bg-slate-800 dark:text-slate-300'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Menu POS Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {filteredMenu.map((item) => (
              <button
                key={item.id}
                onClick={() => addToCart(item)}
                className="p-4 bg-white dark:bg-slate-900 hover:scale-[1.02] active:scale-[0.98] border border-border-secondary rounded-xl text-left flex flex-col justify-between transition-all group min-h-[120px] shadow-sm hover:shadow-md"
              >
                <div>
                  <Badge variant={item.category === 'lunch' ? 'success' : 'primary'} className="mb-2 capitalize">
                    {item.category}
                  </Badge>
                  <h4 className="font-bold text-xs text-slate-800 dark:text-white group-hover:text-primary-600 transition-all">
                    {item.name}
                  </h4>
                </div>
                <div className="flex justify-between items-center w-full mt-4 border-t border-slate-50 dark:border-slate-800 pt-2">
                  <span className="text-[10px] text-slate-400">Price tag:</span>
                  <span className="font-extrabold text-primary-600">{CURRENCY_SYMBOL}{item.price.toFixed(2)}</span>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Right Column - POS Cart Drawer */}
        <Card className="flex flex-col justify-between min-h-[500px]">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ShoppingCart className="text-primary-500" size={18} />
              Sales Ticket Drawer
            </CardTitle>
          </CardHeader>
          <CardBody className="flex-1 flex flex-col justify-between">
            {/* Cart Items List */}
            <div className="flex-1 overflow-y-auto space-y-3 max-h-[280px] pr-1">
              {cart.length > 0 ? (
                cart.map((cartItem) => (
                  <div key={cartItem.id} className="flex justify-between items-center gap-2 p-2 bg-slate-50 dark:bg-slate-900 rounded-lg text-xs">
                    <div className="flex-1">
                      <div className="font-bold text-slate-800 dark:text-white">{cartItem.name}</div>
                      <div className="text-[10px] text-slate-400">{CURRENCY_SYMBOL}{cartItem.price.toFixed(2)}</div>
                    </div>
                    <div className="flex items-center gap-2 bg-white dark:bg-slate-800 border border-border-secondary p-0.5 rounded-lg shrink-0">
                      <button
                        type="button"
                        onClick={() => updateQuantity(cartItem.id, -1)}
                        className="p-1 hover:bg-slate-100 rounded text-slate-500"
                      >
                        <Minus size={10} />
                      </button>
                      <span className="font-bold w-4 text-center">{cartItem.quantity}</span>
                      <button
                        type="button"
                        onClick={() => updateQuantity(cartItem.id, 1)}
                        className="p-1 hover:bg-slate-100 rounded text-slate-500"
                      >
                        <Plus size={10} />
                      </button>
                    </div>
                    <button
                      type="button"
                      onClick={() => removeFromCart(cartItem.id)}
                      className="p-1 hover:bg-rose-50 text-rose-500 rounded shrink-0"
                    >
                      <Trash2 size={12} />
                    </button>
                  </div>
                ))
              ) : (
                <div className="text-center py-12 text-slate-400 text-xs">Cart is empty. Click menu items to add them.</div>
              )}
            </div>

            {/* Checkout Form */}
            <form onSubmit={handleCheckout} className="border-t border-border-secondary pt-4 mt-4 space-y-4">
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => setPaymentMethod('cash')}
                  className={`py-2 px-3 rounded-lg border text-xs font-semibold transition-all ${
                    paymentMethod === 'cash'
                      ? 'border-primary-500 bg-primary-50/50 dark:bg-primary-950/20 text-primary-700 dark:text-primary-300'
                      : 'border-border-secondary text-slate-600 dark:text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  Cash Check
                </button>
                <button
                  type="button"
                  onClick={() => setPaymentMethod('prepaid')}
                  className={`py-2 px-3 rounded-lg border text-xs font-semibold transition-all ${
                    paymentMethod === 'prepaid'
                      ? 'border-primary-500 bg-primary-50/50 dark:bg-primary-950/20 text-primary-700 dark:text-primary-300'
                      : 'border-border-secondary text-slate-600 dark:text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  Student Card (Prepaid)
                </button>
              </div>

              {paymentMethod === 'prepaid' && (
                <Select
                  label="Search Student Account"
                  value={selectedStudentId}
                  onChange={(e) => setSelectedStudentId(e.target.value)}
                  options={studentOptions}
                  required
                />
              )}

              <div className="flex justify-between items-center text-xs pt-2 font-bold">
                <span className="text-slate-500">Ticket Total:</span>
                <span className="text-lg font-extrabold text-primary-600">{CURRENCY_SYMBOL}{cartTotal.toFixed(2)}</span>
              </div>

              <Button
                type="submit"
                variant="primary"
                className="w-full"
                disabled={cart.length === 0}
              >
                Execute Checkout Ticket
              </Button>
            </form>
          </CardBody>
        </Card>
      </div>

      {/* POS Receipt Modal */}
      <Modal
        isOpen={!!receipt}
        onClose={() => setReceipt(null)}
        title="POS Receipt Summary"
        size="sm"
      >
        {receipt && (
          <div className="space-y-4">
            <div className="text-center pb-3 border-b border-dashed border-border-secondary">
              <h3 className="font-extrabold text-slate-800 dark:text-white uppercase tracking-wider text-sm">Camied Behills International School</h3>
              <p className="text-[10px] text-slate-400 mt-1">Accra, Ghana | Canteen POS Ticket</p>
            </div>

            <div className="space-y-1 text-[10px] text-slate-600 dark:text-slate-400 font-mono">
              <div>Receipt ID: {receipt.id}</div>
              <div>Buyer: {receipt.buyerName}</div>
              <div>Payment: {receipt.paymentMethod.toUpperCase()}</div>
              <div>Date: {new Date(receipt.date).toLocaleString('en-GB')}</div>
            </div>

            <table className="w-full text-[10px] text-left text-slate-500 dark:text-slate-400 font-mono border-t border-b border-dashed border-border-secondary py-2">
              <thead>
                <tr className="font-bold">
                  <th className="py-1">Item</th>
                  <th className="py-1 text-center">Qty</th>
                  <th className="py-1 text-right">Price</th>
                </tr>
              </thead>
              <tbody>
                {receipt.items.map((i: any) => (
                  <tr key={i.id}>
                    <td className="py-1">{i.name}</td>
                    <td className="py-1 text-center">{i.quantity}</td>
                    <td className="py-1 text-right">{CURRENCY_SYMBOL}{(i.price * i.quantity).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="flex justify-between items-center text-sm font-extrabold font-mono">
              <span>Grand Total:</span>
              <span>{CURRENCY_SYMBOL}{receipt.total.toFixed(2)}</span>
            </div>

            <div className="flex justify-center pt-4 border-t border-border-secondary">
              <Button
                variant="outline"
                leftIcon={<Printer size={14} />}
                onClick={() => {
                  window.print();
                  setReceipt(null);
                }}
              >
                Print Ticket
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </PageWrapper>
  );
}

import { useState } from 'react';
import { useAuthStore } from '../../../stores/authStore';
import { useCommunication } from '../hooks/useCommunication';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { Textarea } from '../../../components/ui/Textarea';
import { useNotificationStore } from '../../../stores/notificationStore';
import { Plus, Calendar } from 'lucide-react';
import { AnnouncementPriority, AnnouncementTarget } from '../../../types/communication';

export default function AnnouncementsPage() {
  const { user } = useAuthStore();
  const { announcements, createAnnouncement } = useCommunication();
  const addToast = useNotificationStore((state) => state.addToast);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [priority, setPriority] = useState<AnnouncementPriority>('normal');
  const [target, setTarget] = useState<AnnouncementTarget>('all');

  const canPost = user?.role === 'super_admin' || user?.role === 'admin' || user?.role === 'teacher';

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !content) {
      addToast({ type: 'error', message: 'Please complete all required fields.' });
      return;
    }

    createAnnouncement({
      title,
      content,
      authorId: user?.id || 'usr_super',
      authorName: `${user?.firstName} ${user?.lastName}`,
      priority,
      target
    });

    addToast({ type: 'success', message: 'Announcement published successfully!' });
    setIsModalOpen(false);
  };

  const breadcrumbs = [
    { label: 'Communication Hub' },
    { label: 'Announcements' }
  ];

  return (
    <PageWrapper
      title="School Bulletins"
      subtitle="Publish and review circulars, events notice alerts, and general newsletters."
      breadcrumbs={breadcrumbs}
      action={
        canPost ? (
          <Button
            variant="primary"
            leftIcon={<Plus size={16} />}
            onClick={() => {
              setTitle('');
              setContent('');
              setPriority('normal');
              setTarget('all');
              setIsModalOpen(true);
            }}
          >
            Create Notice
          </Button>
        ) : undefined
      }
    >
      <div className="space-y-6">
        <div className="grid grid-cols-1 gap-6">
          {announcements.map((ann) => (
            <Card key={ann.id} className="relative overflow-hidden">
              <div className="h-1 bg-gradient-to-r from-primary-500 to-indigo-600 shrink-0" />
              <CardHeader className="pb-2 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
                <div>
                  <Badge variant={ann.priority === 'urgent' ? 'danger' : ann.priority === 'high' ? 'warning' : 'primary'} className="mb-2 uppercase text-[10px]">
                    {ann.priority} Priority
                  </Badge>
                  <CardTitle className="text-base font-extrabold text-slate-800 dark:text-white mt-1">
                    {ann.title}
                  </CardTitle>
                </div>
                <div className="flex items-center gap-2 text-xs text-slate-400 shrink-0">
                  <Calendar size={14} />
                  <span>{new Date(ann.publishDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}</span>
                </div>
              </CardHeader>
              <CardBody>
                <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed font-light whitespace-pre-line">{ann.content}</p>
                <div className="mt-4 border-t border-slate-50 dark:border-slate-800 pt-2 flex justify-between items-center text-[10px] text-slate-400">
                  <span>Author: {ann.authorName}</span>
                  <Badge variant="neutral" className="capitalize text-[10px]">Audience: {ann.target}</Badge>
                </div>
              </CardBody>
            </Card>
          ))}
        </div>

        {/* Modal Wizard */}
        <Modal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          title="Compose School Circular"
          size="md"
        >
          <form onSubmit={handleSubmit} className="space-y-4">
            <Input
              label="Circular Title"
              placeholder="e.g. Mid-Term Break Notice"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
            <Textarea
              label="Bulletin Body Content"
              placeholder="Detail all dates, timelines, and details..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              required
            />
            <div className="grid grid-cols-2 gap-4">
              <Select
                label="Priority Level"
                value={priority}
                onChange={(e) => setPriority(e.target.value as any)}
                options={[
                  { value: 'low', label: 'Low priority' },
                  { value: 'normal', label: 'Normal priority' },
                  { value: 'high', label: 'High priority' },
                  { value: 'urgent', label: 'Urgent Alert' }
                ]}
              />
              <Select
                label="Target Audience"
                value={target}
                onChange={(e) => setTarget(e.target.value as any)}
                options={[
                  { value: 'all', label: 'Everyone (All)' },
                  { value: 'teachers', label: 'Teachers Only' },
                  { value: 'parents', label: 'Parents Only' },
                  { value: 'students', label: 'Students Only' }
                ]}
              />
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-border-secondary">
              <Button
                variant="outline"
                onClick={() => setIsModalOpen(false)}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="primary"
              >
                Publish Notice
              </Button>
            </div>
          </form>
        </Modal>
      </div>
    </PageWrapper>
  );
}

import { useState } from 'react';
