      action={
        canCreate ? (
          <Button
            variant="primary"
            leftIcon={<Plus size={16} />}
            onClick={() => {
              setTitle('');
              setDescription('');
              setStartDate('');
              setEndDate('');
              setCategory('academic');
              setLocation('');
              setIsModalOpen(true);
