                    </div>
                    <div className="flex-1">
                      <Input 
                        label={`Amount (${CURRENCY_SYMBOL})`}
                        type="number"
                        min="0"
                        step="0.01"
                        value={item.amount}
                        onChange={(e) => handleItemChange(index, 'amount', Number(e.target.value))}
                        required
                      />
                    </div>
                    <div className="flex items-center pb-3 px-2">
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={item.mandatory}
                          onChange={(e) => handleItemChange(index, 'mandatory', e.target.checked)}
                          className="rounded text-primary-600 focus:ring-primary-500 w-4 h-4"
                        />
                        <span className="text-sm font-medium">Mandatory</span>
                      </label>
                    </div>
                    {items.length > 1 && (
                      <Button 
                        type="button" 
                        variant="danger" 
                        size="sm" 
                        className="mb-1"
                        onClick={() => handleRemoveItem(index)}
                      >
                        <Trash2 size={16} />
                      </Button>
                    )}
                  </div>
                ))}
              </div>

              <div className="mt-4 flex justify-end">
                <div className="bg-primary-50 text-primary-900 px-4 py-3 rounded-lg flex items-center gap-4 border border-primary-200">
                  <span className="font-medium">Total Amount:</span>
                  <span className="text-xl font-bold font-heading">
                    {CURRENCY_SYMBOL}{items.reduce((sum, item) => sum + Number(item.amount), 0).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-border-secondary">
              <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>Cancel</Button>
              <Button type="submit" variant="primary">Save Fee Structure</Button>
            </div>
          </form>
        </Modal>
      </div>
    </PageWrapper>
  );
}

import { useState, useCallback, useMemo } from 'react';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { Invoice, IncomeRecord, Budget, Payment, Expense, FinancialSummary } from '../../../types/finance';
import { Student } from '../../../types/student';

export function useFinance() {
  const invoiceAdapter = useMemo(() => new LocalStorageAdapter<Invoice>('advance_invoices'), []);
  const incomeAdapter = useMemo(() => new LocalStorageAdapter<IncomeRecord>('advance_income'), []);
  const budgetAdapter = useMemo(() => new LocalStorageAdapter<Budget>('advance_budgets'), []);
  const paymentAdapter = useMemo(() => new LocalStorageAdapter<Payment>('advance_payments'), []);
  const expenseAdapter = useMemo(() => new LocalStorageAdapter<Expense>('advance_expenses'), []);
  const studentAdapter = useMemo(() => new LocalStorageAdapter<Student>('advance_students'), []);

  const [invoices, setInvoices] = useState<Invoice[]>(() => invoiceAdapter.getAll());
  const [incomeRecords, setIncomeRecords] = useState<IncomeRecord[]>(() => incomeAdapter.getAll());
  const [budgets, setBudgets] = useState<Budget[]>(() => budgetAdapter.getAll());

  const refreshInvoices = useCallback(() => {
    setInvoices(invoiceAdapter.getAll());
  }, [invoiceAdapter]);

  const refreshIncome = useCallback(() => {
    setIncomeRecords(incomeAdapter.getAll());
  }, [incomeAdapter]);

  const refreshBudgets = useCallback(() => {
    setBudgets(budgetAdapter.getAll());
  }, [budgetAdapter]);

  const createInvoice = useCallback((newInvoice: Invoice) => {
    invoiceAdapter.create(newInvoice);
    refreshInvoices();
  }, [invoiceAdapter, refreshInvoices]);

  const updateInvoiceStatus = useCallback((invoiceId: string, status: Invoice['status']) => {
    const existing = invoiceAdapter.getById(invoiceId);
    if (existing) {
      invoiceAdapter.update(invoiceId, { ...existing, status });
      refreshInvoices();
    }
  }, [invoiceAdapter, refreshInvoices]);

  const addIncomeRecord = useCallback((record: IncomeRecord) => {
    incomeAdapter.create(record);
    refreshIncome();
  }, [incomeAdapter, refreshIncome]);

  const saveBudget = useCallback((budget: Budget) => {
    const all = budgetAdapter.getAll();
    const existing = all.find((b) => b.year === budget.year && b.term === budget.term);
    if (existing) {
      budgetAdapter.update(existing.id, budget);
    } else {
      budgetAdapter.create(budget);
    }
    refreshBudgets();
  }, [budgetAdapter, refreshBudgets]);

  const getFinancialSummary = useCallback((): FinancialSummary => {
    const paymentsList = paymentAdapter.getAll();
    const nonFeeIncome = incomeAdapter.getAll();
    const expensesList = expenseAdapter.getAll();

    // Total Fee Income
    const feeIncome = paymentsList.reduce((acc, p) => acc + p.amountPaid, 0);
    // Other Income
    const otherIncome = nonFeeIncome.reduce((acc, i) => acc + i.amount, 0);
    const totalIncome = feeIncome + otherIncome;

    // Approved Expenses
    const totalExpense = expensesList
      .filter((e) => e.status === 'approved')
      .reduce((acc, e) => acc + e.amount, 0);

    const profitOrLoss = totalIncome - totalExpense;

    // Fee collection rate
    // Billed fees = Paid + Outstanding
    const totalCollected = feeIncome;
    const totalOutstanding = paymentsList.reduce((acc, p) => acc + p.balance, 0);
    const totalBilled = totalCollected + totalOutstanding;
    const feeCollectionRate = totalBilled > 0 ? Math.round((totalCollected / totalBilled) * 100) : 100;

    return {
      period: '2025/2026 Academic Year',
      totalIncome,
      totalExpense,
      profitOrLoss,
      feeCollectionRate
    };
  }, [paymentAdapter, incomeAdapter, expenseAdapter]);

  const autoGenerateInvoicesForTerm = useCallback((academicYear: string, term: any) => {
    const studentsList = studentAdapter.getAll();
    const feeStructuresAdapter = new LocalStorageAdapter<any>('advance_fee_structures');
    const structures = feeStructuresAdapter.getAll();

    let createdCount = 0;
    studentsList.forEach((student) => {
      // Find fee structure matching student class and term
      const structure = structures.find(
        (s) => s.classLevel === student.classLevel && s.term === term && s.academicYear === academicYear
      );

      if (structure) {
        // Check if invoice already exists for this student, term, and academicYear
        const exists = invoiceAdapter.getAll().some(
          (inv) => inv.studentId === student.id && inv.dueDate.includes(academicYear.split('/')[0]) // simple check
        );

        if (!exists) {
          const newInvoice: Invoice = {
            id: `inv_${Math.random().toString(36).substring(7)}`,
            studentId: student.id,
            date: new Date().toISOString().split('T')[0],
            dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 30 days due
            items: structure.items.map((i: any) => ({
              description: i.description,
              amount: i.amount
            })),
            total: structure.totalAmount,
            status: 'sent'
          };
          invoiceAdapter.create(newInvoice);
          createdCount++;
        }
      }
    });

    if (createdCount > 0) refreshInvoices();
    return createdCount;
  }, [studentAdapter, invoiceAdapter, refreshInvoices]);

  return {
    invoices,
    incomeRecords,
    budgets,
    createInvoice,
    updateInvoiceStatus,
    addIncomeRecord,
    saveBudget,
    getFinancialSummary,
    autoGenerateInvoicesForTerm,
    refreshInvoices,
    refreshIncome,
    refreshBudgets
  };
}

import { useState, useMemo } from 'react';
import { useFinance } from '../hooks/useFinance';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { Student } from '../../../types/student';
import { Invoice } from '../../../types/finance';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { useNotificationStore } from '../../../stores/notificationStore';
import { Plus, RefreshCw, Trash2 } from 'lucide-react';

export default function InvoicesPage() {
  const { invoices, createInvoice, updateInvoiceStatus, autoGenerateInvoicesForTerm } = useFinance();
  const addToast = useNotificationStore((state) => state.addToast);

  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);

  // Individual Invoice Form state
  const [selectedStudentId, setSelectedStudentId] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [invoiceItems, setInvoiceItems] = useState<{ description: string; amount: number }[]>([
    { description: 'Tuition Fee', amount: 0 }
  ]);

  // Bulk Invoice Form state
  const [bulkYear, setBulkYear] = useState('2025/2026');
  const [bulkTerm, setBulkTerm] = useState('Term 2');

  const studentsList = useMemo(() => {
    return new LocalStorageAdapter<Student>('advance_students').getAll();
  }, []);

  const handleAddInvoiceItem = () => {
    setInvoiceItems((prev) => [...prev, { description: '', amount: 0 }]);
  };

  const handleRemoveInvoiceItem = (index: number) => {
    setInvoiceItems((prev) => prev.filter((_, idx) => idx !== index));
  };

  const handleItemChange = (index: number, field: 'description' | 'amount', value: string | number) => {
    setInvoiceItems((prev) => {
      const updated = [...prev];
      if (field === 'amount') {
        updated[index].amount = Number(value);
      } else {
        updated[index].description = String(value);
      }
      return updated;
    });
  };

  const handleCreateInvoice = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudentId || !dueDate) {
      addToast({ type: 'error', message: 'Please select a student and specify a due date.' });
      return;
    }

    const validItems = invoiceItems.filter((i) => i.description && i.amount > 0);
    if (validItems.length === 0) {
      addToast({ type: 'error', message: 'Invoice must contain at least one item with amount > 0.' });
      return;
    }

    const total = validItems.reduce((acc, item) => acc + item.amount, 0);

    const newInvoice: Invoice = {
      id: `inv_${Math.random().toString(36).substring(7)}`,
      studentId: selectedStudentId,
      date: new Date().toISOString().split('T')[0],
      dueDate,
      items: validItems,
      total,
      status: 'sent'
    };

    createInvoice(newInvoice);
    addToast({ type: 'success', message: 'Invoice created and issued successfully!' });
    setIsInvoiceModalOpen(false);
  };

  const handleBulkGenerate = (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const count = autoGenerateInvoicesForTerm(bulkYear, bulkTerm);
      if (count > 0) {
        addToast({ type: 'success', message: `Successfully generated ${count} term invoices based on active configurations!` });
      } else {
        addToast({ type: 'warning', message: 'No new invoices generated. All eligible students already have invoices for this term.' });
      }
      setIsBulkModalOpen(false);
    } catch (err: any) {
      addToast({ type: 'error', message: err.message || 'Bulk generation failed.' });
    }
  };

  const handleMarkPaid = (id: string) => {
    updateInvoiceStatus(id, 'paid');
    addToast({ type: 'success', message: 'Invoice status updated to Paid.' });
  };

  const getStudentName = (studentId: string) => {
    const s = studentsList.find((st) => st.id === studentId);
    return s ? `${s.firstName} ${s.lastName} (${s.classLevel})` : studentId;
  };

  const columns: Column<Invoice>[] = [
    {
      header: 'Invoice ID',
      accessorKey: 'id',
      sortable: true,
      cell: (item) => <span className="font-mono text-xs font-semibold">{item.id}</span>
    },
    {
      header: 'Student',
      accessorKey: 'studentId',
      sortable: true,
      cell: (item) => getStudentName(item.studentId)
    },
    {
      header: 'Date Billed',
      accessorKey: 'date',
      cell: (item) => new Date(item.date).toLocaleDateString('en-GB')
    },
    {
      header: 'Due Date',
      accessorKey: 'dueDate',
      cell: (item) => new Date(item.dueDate).toLocaleDateString('en-GB')
    },
    {
      header: 'Total Amount',
      accessorKey: 'total',
      sortable: true,
      cell: (item) => `${CURRENCY_SYMBOL}${item.total.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`
    },
    {
      header: 'Status',
      accessorKey: 'status',
      sortable: true,
      cell: (item) => {
        const variants: Record<string, 'success' | 'primary' | 'warning' | 'danger' | 'neutral'> = {
          paid: 'success',
          sent: 'primary',
          draft: 'neutral',
          overdue: 'danger'
        };
        return <Badge variant={variants[item.status] || 'neutral'}>{item.status}</Badge>;
      }
    },
    {
      header: 'Actions',
      accessorKey: 'id',
      cell: (item) => (
        <div className="flex gap-2">
          {item.status !== 'paid' && (
            <Button 
              variant="outline" 
              size="sm" 
              onClick={() => handleMarkPaid(item.id)}
            >
              Mark Paid
            </Button>
          )}
        </div>
      )
    }
  ];

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Finance' },
    { label: 'Invoices' }
  ];

  return (
    <PageWrapper 
      title="Student Invoicing Ledger" 
      subtitle="Manage tuition billing receipts, view payment timelines, and run batch invoicing workflows."
      breadcrumbs={breadcrumbs}
      action={
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => setIsBulkModalOpen(true)} leftIcon={<RefreshCw size={16} />}>
            Bulk Generate
          </Button>
          <Button variant="primary" onClick={() => setIsInvoiceModalOpen(true)} leftIcon={<Plus size={16} />}>
            Create Invoice
          </Button>
        </div>
      }
    >
      <Card>
        <CardBody>
          <DataTable 
            data={invoices} 
            columns={columns} 
            searchKey="studentId" 
            searchPlaceholder="Search invoices by Student ID..." 
            pageSize={10} 
          />
        </CardBody>
      </Card>

      {/* Individual Invoice Modal */}
      <Modal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        title="Create Student Invoice"
        size="lg"
      >
        <form onSubmit={handleCreateInvoice} className="space-y-6">
          <Select
            label="Select Student *"
            value={selectedStudentId}
            onChange={(e) => setSelectedStudentId(e.target.value)}
            options={studentsList.map((s) => ({
              value: s.id,
              label: `${s.firstName} ${s.lastName} [${s.classLevel}] - ID: ${s.studentId}`
            }))}
            placeholder="Search and select student..."
          />

          <Input
            label="Due Date *"
            type="date"
            value={dueDate}
            onChange={(e) => setDueDate(e.target.value)}
            required
          />

          <div className="border border-slate-200 dark:border-slate-800 rounded-xl p-4 space-y-4">
            <div className="flex justify-between items-center">
              <h4 className="font-semibold text-slate-800 dark:text-slate-200 text-sm">Invoice Items</h4>
              <Button type="button" variant="outline" size="sm" onClick={handleAddInvoiceItem}>
                Add Item
              </Button>
            </div>

            <div className="space-y-3">
              {invoiceItems.map((item, idx) => (
                <div key={idx} className="flex gap-3 items-end">
                  <div className="flex-1">
                    <Input
                      placeholder="e.g. Feeding Fee"
                      value={item.description}
                      onChange={(e) => handleItemChange(idx, 'description', e.target.value)}
                      required
                    />
                  </div>
                  <div className="w-32">
                    <Input
                      type="number"
                      placeholder="0.00"
                      value={item.amount || ''}
                      onChange={(e) => handleItemChange(idx, 'amount', e.target.value)}
                      required
                    />
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    onClick={() => handleRemoveInvoiceItem(idx)}
                    disabled={invoiceItems.length === 1}
                    className="text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/20 mb-5"
                  >
                    <Trash2 size={16} />
                  </Button>
                </div>
              ))}
            </div>
          </div>

          <div className="flex justify-end gap-3 border-t border-slate-200 dark:border-slate-800 pt-4">
            <Button variant="secondary" type="button" onClick={() => setIsInvoiceModalOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" type="submit">
              Issue Invoice
            </Button>
          </div>
        </form>
      </Modal>

      {/* Bulk Generate Modal */}
      <Modal
        isOpen={isBulkModalOpen}
        onClose={() => setIsBulkModalOpen(false)}
        title="Batch Term Billing Generator"
        size="md"
      >
        <form onSubmit={handleBulkGenerate} className="space-y-4">
          <p className="text-sm text-slate-500">
            This operation automatically queries active students, detects their corresponding class fee structures, and issues a standard tuition invoice in draft status.
          </p>
          <Input
            label="Academic Year *"
            value={bulkYear}
            onChange={(e) => setBulkYear(e.target.value)}
            required
          />
          <Select
            label="Billing Term *"
            value={bulkTerm}
            onChange={(e) => setBulkTerm(e.target.value)}
            options={[
              { value: 'Term 1', label: 'Term 1' },
              { value: 'Term 2', label: 'Term 2' },
              { value: 'Term 3', label: 'Term 3' }
            ]}
          />
          <div className="flex justify-end gap-3 pt-4 border-t border-slate-200 dark:border-slate-800">
            <Button variant="secondary" type="button" onClick={() => setIsBulkModalOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" type="submit">
              Run Invoice Generator
            </Button>
          </div>
        </form>
      </Modal>
    </PageWrapper>
  );
}

import React, { useState, useMemo } from 'react';
import { usePayroll } from '../hooks/usePayroll';
import { useAuthStore } from '../../../stores/authStore';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardHeader, CardTitle, CardBody } from '../../../components/ui/Card';
import { StatCard } from '../../../components/data-display/StatCard';
import { Button } from '../../../components/ui/Button';
import { Modal } from '../../../components/ui/Modal';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { useNotificationStore } from '../../../stores/notificationStore';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Banknote, Users, FileSpreadsheet, RefreshCw } from 'lucide-react';

const MONTHS_OPTIONS = [
  { value: '2026-01', label: 'January 2026' },
  { value: '2026-02', label: 'February 2026' },
  { value: '2026-03', label: 'March 2026' },
  { value: '2026-04', label: 'April 2026' },
  { value: '2026-05', label: 'May 2026' },
  { value: '2026-06', label: 'June 2026' }
];

export default function PayrollDashboardPage() {
  const { payslips, runMonthlyPayroll, getPayrollSummary } = usePayroll();
  const { user } = useAuthStore();
  const addToast = useNotificationStore((state) => state.addToast);

  const [selectedMonth, setSelectedMonth] = useState('2026-06');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [payrollMonth, setPayrollMonth] = useState('2026-06');

  const monthlySummary = useMemo(() => {
    return getPayrollSummary(selectedMonth);
  }, [getPayrollSummary, selectedMonth, payslips]);

  const recentPayslips = useMemo(() => {
    return [...payslips]
      .filter((p) => p.month === selectedMonth)
      .slice(0, 5);
  }, [payslips, selectedMonth]);

  const chartData = useMemo(() => {
    return MONTHS_OPTIONS.map((m) => {
      const sum = getPayrollSummary(m.value);
      return {
        month: m.label.split(' ')[0],
        cost: sum.totalNet
      };
    });
  }, [getPayrollSummary, payslips]);

  const handleRunPayroll = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    try {
      const count = runMonthlyPayroll(payrollMonth, user.id);
      if (count > 0) {
        addToast({ type: 'success', message: `Payroll ran successfully! Generated ${count} employees payslips.` });
      } else {
        addToast({ type: 'warning', message: 'No new payslips generated. Payroll already ran for this month.' });
      }
      setIsModalOpen(false);
    } catch (err: any) {
      addToast({ type: 'error', message: err.message || 'Failed to run payroll.' });
    }
  };

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Payroll' },
    { label: 'Overview' }
  ];

  return (
    <PageWrapper 
      title="Institutional Payroll Dashboard" 
      subtitle="Examine payroll disbursements, process employee salary slips, and monitor salary expenditures."
      breadcrumbs={breadcrumbs}
      action={
        <Button variant="primary" onClick={() => setIsModalOpen(true)} leftIcon={<RefreshCw size={16} />}>
          Run Payroll
        </Button>
      }
    >
      <div className="space-y-6">
        {/* Month selector */}
        <div className="flex justify-end">
          <div className="w-48">
            <Select
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
              options={MONTHS_OPTIONS}
            />
          </div>
        </div>

        {/* KPI Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard
            title="Net Salary Payout"
            value={`${CURRENCY_SYMBOL}${monthlySummary.totalNet.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`}
            icon={<Banknote className="text-emerald-500" />}
            description={`Salary pool for ${selectedMonth}`}
          />
          <StatCard
            title="Staff Paid Count"
            value={monthlySummary.count}
            icon={<Users className="text-primary-500" />}
            description="Active payroll slips"
          />
          <StatCard
            title="Deductions Collected"
            value={`${CURRENCY_SYMBOL}${monthlySummary.totalDeductions.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`}
            icon={<FileSpreadsheet className="text-slate-500" />}
            description="Taxes & SSNIT deductions"
          />
        </div>

        {/* Chart vs Recent Payslips */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Cost Trend Chart */}
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle>Payroll Cost Trend</CardTitle>
            </CardHeader>
            <CardBody>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" className="stroke-slate-200 dark:stroke-slate-800" />
                    <XAxis dataKey="month" className="text-xs text-slate-500" />
                    <YAxis className="text-xs text-slate-500" />
                    <Tooltip 
                      formatter={(value) => `${CURRENCY_SYMBOL}${value.toLocaleString()}`}
                      contentStyle={{ 
                        backgroundColor: 'var(--color-surface-primary)', 
                        borderColor: 'var(--color-border-primary)',
                        borderRadius: 'var(--radius-lg)'
                      }} 
                    />
                    <Bar dataKey="cost" name="Salary Cost" fill="var(--color-primary-500)" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </CardBody>
          </Card>

          {/* Recent Payslips */}
          <Card>
            <CardHeader>
              <CardTitle>Recent Payslips</CardTitle>
            </CardHeader>
            <CardBody className="space-y-4">
              {recentPayslips.length > 0 ? (
                recentPayslips.map((pay) => (
                  <div key={pay.id} className="flex items-center justify-between p-3 border border-slate-100 dark:border-slate-800 rounded-xl">
                    <div>
                      <h4 className="text-sm font-semibold text-slate-800 dark:text-slate-200">Employee ID: {pay.staffId}</h4>
                      <p className="text-xs text-slate-400 mt-0.5">Net Pay: {CURRENCY_SYMBOL}{pay.netSalary.toLocaleString()}</p>
                    </div>
                    <Badge variant={pay.status === 'paid' ? 'success' : 'warning'}>{pay.status}</Badge>
                  </div>
                ))
              ) : (
                <div className="py-6 text-center text-slate-400 text-sm">No slips logged for this month.</div>
              )}
            </CardBody>
          </Card>
        </div>
      </div>

      {/* Run Payroll Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title="Run Monthly Payroll"
        size="md"
      >
        <form onSubmit={handleRunPayroll} className="space-y-4">
          <p className="text-sm text-slate-500">
            Running payroll will query all active staff members, compute their allowances and standard Ghanaian tax deductions (SSNIT/Income Tax), and generate payslip logs.
          </p>
          <Select
            label="Payroll Month *"
            value={payrollMonth}
            onChange={(e) => setPayrollMonth(e.target.value)}
            options={MONTHS_OPTIONS}
          />
          <div className="flex justify-end gap-3 pt-4 border-t border-slate-200 dark:border-slate-800">
            <Button variant="secondary" type="button" onClick={() => setIsModalOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" type="submit">
              Generate Payroll Slips
            </Button>
          </div>
        </form>
      </Modal>
    </PageWrapper>
  );
}

import { useMemo } from 'react';
import { usePayroll } from '../hooks/usePayroll';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody, CardHeader, CardTitle } from '../../../components/ui/Card';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { Button } from '../../../components/ui/Button';
import { EmptyState } from '../../../components/data-display/EmptyState';
import { StatCard } from '../../../components/data-display/StatCard';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { Calendar, Users, Wallet, CreditCard, ChevronRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const MONTH_NAMES: Record<string, string> = {
  '2026-01': 'January 2026',
  '2026-02': 'February 2026',
  '2026-03': 'March 2026',
  '2026-04': 'April 2026',
  '2026-05': 'May 2026',
  '2026-06': 'June 2026',
};

interface HistoryRecord {
  monthCode: string;
  monthName: string;
  totalEmployees: number;
  totalBasic: number;
  totalAllowances: number;
  totalDeductions: number;
  totalNet: number;
  status: string;
}

export default function PayrollHistoryPage() {
  const { payslips } = usePayroll();
  const navigate = useNavigate();

  const historyData = useMemo(() => {
    // Group payslips by month
    const groups: Record<string, typeof payslips> = {};
    payslips.forEach(p => {
      if (!groups[p.month]) {
        groups[p.month] = [];
      }
      groups[p.month].push(p);
    });

    const records: HistoryRecord[] = Object.entries(groups).map(([month, slips]) => {
      const totalBasic = slips.reduce((sum, s) => sum + s.basicSalary, 0);
      const totalAllowances = slips.reduce((sum, s) => sum + s.allowances.reduce((acc, a) => acc + a.amount, 0), 0);
      const totalDeductions = slips.reduce((sum, s) => sum + s.deductions.reduce((acc, d) => acc + d.amount, 0), 0);
      const totalNet = slips.reduce((sum, s) => sum + s.netSalary, 0);

      return {
        monthCode: month,
        monthName: MONTH_NAMES[month] || month,
        totalEmployees: slips.length,
        totalBasic,
        totalAllowances,
        totalDeductions,
        totalNet,
        status: 'Processed & Disbursed'
      };
    });

    // Sort descending by month code
    return records.sort((a, b) => b.monthCode.localeCompare(a.monthCode));
  }, [payslips]);

  const stats = useMemo(() => {
    const totalDisbursed = historyData.reduce((sum, r) => sum + r.totalNet, 0);
    const totalTransactions = historyData.reduce((sum, r) => sum + r.totalEmployees, 0);
    const uniqueMonths = historyData.length;
    return {
      totalDisbursed,
      totalTransactions,
      uniqueMonths,
      avgMonthCost: uniqueMonths > 0 ? (totalDisbursed / uniqueMonths) : 0
    };
  }, [historyData]);

  const columns: Column<HistoryRecord>[] = [
    {
      header: 'Pay Cycle Month',
      accessorKey: 'monthName',
      cell: (row) => (
        <div className="flex items-center gap-3">
          <div className="p-2 bg-primary-50 dark:bg-primary-950/20 text-primary-600 rounded-lg">
            <Calendar size={16} />
          </div>
          <div>
            <span className="font-semibold text-slate-900 dark:text-white">{row.monthName}</span>
            <div className="text-[10px] text-slate-400 font-mono">{row.monthCode}</div>
          </div>
        </div>
      )
    },
    {
      header: 'Employees Paid',
      accessorKey: 'totalEmployees',
      cell: (row) => (
        <span className="font-medium text-slate-800 dark:text-slate-200">{row.totalEmployees} Staff</span>
      )
    },
    {
      header: 'Salary Subtotal',
      accessorKey: 'totalBasic',
      cell: (row) => (
        <span className="font-mono text-xs text-slate-600 dark:text-slate-400">
          {CURRENCY_SYMBOL}{row.totalBasic.toLocaleString(undefined, { minimumFractionDigits: 2 })}
        </span>
      )
    },
    {
      header: 'Total Net Payout',
      accessorKey: 'totalNet',
      cell: (row) => (
        <span className="font-extrabold text-emerald-600 dark:text-emerald-450">
          {CURRENCY_SYMBOL}{row.totalNet.toLocaleString(undefined, { minimumFractionDigits: 2 })}
        </span>
      )
    },
    {
      header: 'Disbursement Status',
      accessorKey: 'status',
      cell: (row) => (
        <Badge variant="success" className="capitalize">
          {row.status}
        </Badge>
      )
    },
    {
      header: 'Action',
      accessorKey: 'monthCode' as any,
      cell: (row) => (
        <Button
          variant="ghost"
          size="sm"
          className="text-primary-600 hover:text-primary-700 hover:bg-primary-50 dark:hover:bg-primary-950/30 flex items-center gap-1"
          onClick={() => navigate(`/payroll/payslips?month=${row.monthCode}`)}
        >
          View Slips <ChevronRight size={14} />
        </Button>
      )
    }
  ];

  return (
    <PageWrapper
      title="Payroll Disbursement History"
      subtitle="Track monthly school payroll disbursements, total net payouts, and employee counts."
      breadcrumbs={[
        { label: 'Payroll Management', path: '/payroll' },
        { label: 'History' }
      ]}
    >
      {/* Stats row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard
          title="Total Paid (All-Time)"
          value={`${CURRENCY_SYMBOL}${stats.totalDisbursed.toLocaleString()}`}
          icon={<Wallet className="text-success-500" />}
        />
        <StatCard
          title="Payslips Generated"
          value={stats.totalTransactions}
          icon={<Users className="text-primary-500" />}
        />
        <StatCard
          title="Avg. Monthly Payout"
          value={`${CURRENCY_SYMBOL}${stats.avgMonthCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}`}
          icon={<CreditCard className="text-indigo-500" />}
        />
        <StatCard
          title="Completed Pay Cycles"
          value={stats.uniqueMonths}
          icon={<Calendar className="text-warning-500" />}
        />
      </div>

      {/* Main Table Card */}
      <Card>
        <CardHeader>
          <CardTitle>Historical Pay Runs</CardTitle>
        </CardHeader>
        <CardBody className="p-0">
          {historyData.length > 0 ? (
            <DataTable data={historyData} columns={columns} />
          ) : (
            <div className="p-6">
              <EmptyState
                title="No Payroll Runs"
                description="No payroll historical run records found in the system database."
              />
            </div>
          )}
        </CardBody>
      </Card>
    </PageWrapper>
  );
}

import { useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { usePayroll } from '../hooks/usePayroll';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { LocalStorageAdapter } from '../../../services/adapters/localStorageAdapter';
import { Staff } from '../../../types/staff';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { useNotificationStore } from '../../../stores/notificationStore';
import { Download, ArrowLeft } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

export default function PayslipDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { payslips } = usePayroll();
  const addToast = useNotificationStore((state) => state.addToast);
  const printAreaRef = useRef<HTMLDivElement>(null);

  const payslip = useMemo(() => {
    return payslips.find((p) => p.id === id);
  }, [payslips, id]);

  const staff = useMemo(() => {
    if (!payslip) return null;
    return new LocalStorageAdapter<Staff>('advance_staff').getById(payslip.staffId);
  }, [payslip]);

  const formattedMonth = useMemo(() => {
    if (!payslip) return '';
    const [year, monthNum] = payslip.month.split('-');
    const date = new Date(Number(year), Number(monthNum) - 1, 1);
    return date.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  }, [payslip]);

  const handleDownloadPDF = async () => {
    const element = printAreaRef.current;
    if (!element || !payslip) return;

    try {
      addToast({ type: 'info', message: 'Generating PDF document, please wait...' });
      const canvas = await html2canvas(element, { scale: 2 });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgWidth = 190; // margins
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 10, 10, imgWidth, imgHeight);
      pdf.save(`payslip-${payslip.staffId}-${payslip.month}.pdf`);
      addToast({ type: 'success', message: 'PDF downloaded successfully!' });
    } catch (error) {
      addToast({ type: 'error', message: 'Failed to generate PDF.' });
    }
  };

  if (!payslip) {
    return (
      <div className="py-12 text-center text-slate-500">
        <p>Payslip not found.</p>
        <Button variant="secondary" onClick={() => navigate('/payroll/payslips')} className="mt-4">
          Back to List
        </Button>
      </div>
    );
  }

  const totalEarnings = payslip.basicSalary + payslip.allowances.reduce((acc, a) => acc + a.amount, 0);
  const totalDeductions = payslip.deductions.reduce((acc, d) => acc + d.amount, 0);

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Payroll', path: '/payroll' },
    { label: 'Payslips', path: '/payroll/payslips' },
    { label: 'Payslip Details' }
  ];

  return (
    <PageWrapper 
      title="Salary Payslip details" 
      subtitle="Examine granular employee pay stubs, allowances, and statutory deduction details."
      breadcrumbs={breadcrumbs}
      action={
        <div className="flex gap-2">
          <Button variant="secondary" onClick={() => navigate('/payroll/payslips')} leftIcon={<ArrowLeft size={16} />}>
            Back
          </Button>
          <Button variant="primary" onClick={handleDownloadPDF} leftIcon={<Download size={16} />}>
            Export PDF
          </Button>
        </div>
      }
    >
      <div className="max-w-3xl mx-auto space-y-6">
        <Card className="shadow-2xl">
          <CardBody className="p-8 space-y-8" ref={printAreaRef} id="payslip-print-area">

            {/* Header / Brand block */}
            <div className="flex justify-between items-start border-b border-slate-200 dark:border-slate-800 pb-6">
              <div className="flex items-center gap-3">
                <div className="w-16 h-16 flex items-center justify-center shrink-0">
                  <img src="/logo_transparent.png" alt="School Logo" className="w-full h-full object-contain" />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white leading-tight font-heading">
                    Camied Behills
                  </h2>
                  <p className="text-xs text-slate-500">International School</p>
                  <p className="text-[10px] text-slate-400 font-mono italic">Motto: Scientia Potestas Est</p>
                </div>
              </div>
              <div className="text-right">
                <h3 className="text-lg font-bold text-primary-600 dark:text-primary-400 uppercase tracking-wider">Salary Payslip</h3>
                <p className="text-sm font-semibold text-slate-500 mt-1">{formattedMonth}</p>
                <p className="text-[10px] text-slate-400 font-mono mt-1">Ref ID: {payslip.id}</p>
              </div>
            </div>

            {/* Employee Metadata */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4 bg-slate-50 dark:bg-slate-800/20 border border-slate-200 dark:border-slate-800 rounded-xl text-sm">
              <div className="space-y-2">
                <div>
                  <span className="text-slate-400 text-xs">Employee Name</span>
                  <p className="font-semibold text-slate-800 dark:text-slate-200">
                    {staff ? `${staff.firstName} ${staff.lastName}` : 'N/A'}
                  </p>
                </div>
                <div>
                  <span className="text-slate-400 text-xs">Staff ID</span>
                  <p className="font-semibold text-slate-800 dark:text-slate-200 font-mono">{staff?.staffId || payslip.staffId}</p>
                </div>
                <div>
                  <span className="text-slate-400 text-xs">Designation / Role</span>
                  <p className="font-semibold text-slate-800 dark:text-slate-200 capitalize">{staff?.role.replace('_', ' ') || 'Staff'}</p>
                </div>
              </div>

              <div className="space-y-2">
                <div>
                  <span className="text-slate-400 text-xs">Bank Details</span>
                  <p className="font-semibold text-slate-800 dark:text-slate-200">
                    {staff?.bankAccount?.bankName || 'N/A'}
                  </p>
                </div>
                <div>
                  <span className="text-slate-400 text-xs">Account Name</span>
                  <p className="font-semibold text-slate-800 dark:text-slate-200">
                    {staff?.bankAccount?.accountName || 'N/A'}
                  </p>
                </div>
