import { useState, useMemo } from 'react';
import { useFinance } from '../../finance/hooks/useFinance';
import { useAdmin } from '../../admin/hooks/useAdmin';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Tabs } from '../../../components/ui/Tabs';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Badge } from '../../../components/ui/Badge';
import { CURRENCY_SYMBOL } from '../../../types/common';
import { DollarSign, Wallet, ShieldAlert } from 'lucide-react';

export default function FinancialReportsPage() {
  const { getFinancialSummary, invoices, incomeRecords } = useFinance();
  const { expenses, logs } = useAdmin();

  const [activeTab, setActiveTab] = useState('pl');

  const summary = useMemo(() => getFinancialSummary(), [getFinancialSummary]);

  // Compile Profit & Loss line items
  const plData = useMemo(() => {
    const list: { type: 'income' | 'expense'; category: string; description: string; amount: number; date: string }[] = [];

    // Add income records
    incomeRecords.forEach((i) => {
      list.push({
        type: 'income',
        category: i.source,
        description: i.description,
        amount: i.amount,
        date: i.date
      });
    });

    // Add approved expenses
    expenses
      .filter((e) => e.status === 'approved')
      .forEach((e) => {
        list.push({
          type: 'expense',
          category: e.category,
          description: e.description,
          amount: e.amount,
          date: e.date
        });
      });

    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [incomeRecords, expenses]);

  const plColumns: Column<any>[] = [
    {
      header: 'Date',
      accessorKey: 'date',
      sortable: true,
      cell: (item) => new Date(item.date).toLocaleDateString('en-GB')
    },
    {
      header: 'Entry Type',
      accessorKey: 'type',
      sortable: true,
      cell: (item) => (
        <Badge variant={item.type === 'income' ? 'success' : 'danger'} className="capitalize">
          {item.type}
        </Badge>
      )
    },
    {
      header: 'Category / Source',
      accessorKey: 'category',
      sortable: true,
      cell: (item) => <span className="capitalize">{item.category.replace('_', ' ')}</span>
    },
    {
      header: 'Description',
      accessorKey: 'description'
    },
    {
      header: 'Amount',
      accessorKey: 'amount',
      sortable: true,
      cell: (item) => (
        <span className={item.type === 'income' ? 'text-emerald-600 font-bold' : 'text-rose-600 font-bold'}>
          {item.type === 'income' ? '+' : '-'}{CURRENCY_SYMBOL}{item.amount.toLocaleString('en-GH', { minimumFractionDigits: 2 })}
        </span>
      )
    }
  ];

  // Compile Fee Payments
  const feePaymentData = useMemo(() => {
    const list: { id: string; invoiceId: string; amount: number; date: string; status: string }[] = [];
    invoices.forEach((inv) => {
      list.push({
        id: inv.id,
        invoiceId: inv.id,
        amount: inv.total,
        date: inv.date,
        status: inv.status
      });
    });
    return list;
  }, [invoices]);

  const feeColumns: Column<any>[] = [
    {
      header: 'Invoice ID',
      accessorKey: 'invoiceId',
      sortable: true,
      cell: (item) => <span className="font-mono text-xs">{item.invoiceId}</span>
    },
    {
      header: 'Billed Value',
      accessorKey: 'amount',
      sortable: true,
      cell: (item) => `${CURRENCY_SYMBOL}${item.amount.toLocaleString()}`
    },
    {
      header: 'Date Issued',
      accessorKey: 'date',
      cell: (item) => new Date(item.date).toLocaleDateString('en-GB')
    },
    {
      header: 'Status',
      accessorKey: 'status',
      sortable: true,
      cell: (item) => (
        <Badge variant={item.status === 'paid' ? 'success' : item.status === 'sent' ? 'primary' : 'warning'}>
          {item.status}
        </Badge>
      )
    }
  ];

  const tabs = [
    { id: 'pl', label: 'Profit & Loss Statement', icon: <DollarSign size={16} /> },
    { id: 'fees', label: 'Fee Payments Summary', icon: <Wallet size={16} /> },
    { id: 'audit', label: 'Audit Logs Ledger', icon: <ShieldAlert size={16} /> }
  ];

  const breadcrumbs = [
    { label: 'Dashboard', path: '/dashboard' },
    { label: 'Reports' },
    { label: 'Financial Reports' }
  ];

  return (
    <PageWrapper 
      title="Institutional Financial Statements" 
      subtitle="Examine profit and loss accounts, tuition ledger collection, and administrative security logs."
      breadcrumbs={breadcrumbs}
    >
      <div className="space-y-6">
        <Tabs tabs={tabs} activeTab={activeTab} onChange={setActiveTab} variant="line" />

        {activeTab === 'pl' && (
          <div className="space-y-6 animate-fade-in">
            {/* Overview Card */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 p-6 bg-slate-50 dark:bg-slate-800/20 border border-slate-200 dark:border-slate-800 rounded-xl">
              <div>
                <span className="text-slate-400 text-xs uppercase font-semibold">Total Revenue (YTD)</span>
                <h3 className="text-2xl font-bold text-slate-800 dark:text-white font-heading mt-1">
                  {CURRENCY_SYMBOL}{summary.totalIncome.toLocaleString()}
                </h3>
              </div>
              <div>
                <span className="text-slate-400 text-xs uppercase font-semibold">Approved Expenditures</span>
                <h3 className="text-2xl font-bold text-slate-800 dark:text-white font-heading mt-1">
                  {CURRENCY_SYMBOL}{summary.totalExpense.toLocaleString()}
                </h3>
              </div>
              <div>
                <span className="text-slate-400 text-xs uppercase font-semibold">Net Statement Balance</span>
                <h3 className={`text-2xl font-extrabold font-heading mt-1 ${summary.profitOrLoss >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                  {summary.profitOrLoss >= 0 ? '+' : ''}{CURRENCY_SYMBOL}{summary.profitOrLoss.toLocaleString()}
                </h3>
              </div>
            </div>

            <Card>
              <CardBody>
                <DataTable 
                  data={plData} 
                  columns={plColumns} 
                  searchKey="description" 
                  searchPlaceholder="Search P&L entries..." 
                  pageSize={15} 
                />
              </CardBody>
            </Card>
          </div>
        )}

        {activeTab === 'fees' && (
          <div className="space-y-6 animate-fade-in">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-6 bg-slate-50 dark:bg-slate-800/20 border border-slate-200 dark:border-slate-800 rounded-xl">
              <div>
                <span className="text-slate-400 text-xs uppercase font-semibold">Collection Progress Rate</span>
                <h3 className="text-3xl font-extrabold text-primary-600 font-heading mt-1">
                  {summary.feeCollectionRate}%
                </h3>
              </div>
              <div>
                <span className="text-slate-400 text-xs uppercase font-semibold">Active Billing Cycles</span>
                <h3 className="text-2xl font-bold text-slate-800 dark:text-white font-heading mt-1">
                  {summary.period}
                </h3>
              </div>
            </div>

            <Card>
              <CardBody>
                <DataTable 
                  data={feePaymentData} 
                  columns={feeColumns} 
                  searchKey="invoiceId" 
                  searchPlaceholder="Search billing sheets..." 
                  pageSize={10} 
                />
              </CardBody>
            </Card>
          </div>
        )}

        {activeTab === 'audit' && (
          <Card className="animate-fade-in">
            <CardBody>
              <DataTable 
                data={logs} 
                columns={[
                  {
                    header: 'Timestamp',
                    accessorKey: 'timestamp',
                    cell: (item) => new Date(item.timestamp).toLocaleString('en-GB')
                  },
                  {
                    header: 'Administrator',
                    accessorKey: 'userName',
                    cell: (item) => <span className="font-semibold">{item.userName}</span>
                  },
                  {
                    header: 'Audit Action',
                    accessorKey: 'action',
                    cell: (item) => (
                      <Badge variant="neutral" className="font-mono text-[9px] uppercase">
                        {item.action}
                      </Badge>
                    )
                  },
                  {
                    header: 'Details Description',
                    accessorKey: 'details'
                  }
                ]} 
                searchKey="userName" 
                searchPlaceholder="Search audit trails..." 
                pageSize={15} 
              />
            </CardBody>
          </Card>
        )}
      </div>
    </PageWrapper>
  );
}

import React, { useState } from 'react';
import { useStaff } from '../hooks/useStaff';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody, CardFooter } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { useNotificationStore } from '../../../stores/notificationStore';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Save, UserPlus } from 'lucide-react';
import { StaffRole } from '../../../types';

export default function StaffRegisterPage() {
  const navigate = useNavigate();
  const { registerStaff } = useStaff();
  const addToast = useNotificationStore(state => state.addToast);

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    role: 'teacher' as StaffRole,
    qualification: '',
    salary: 3000,
    bankName: '',
    accountName: '',
    accountNumber: '',
  });

  const handleInputChange = (field: string, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.firstName || !formData.lastName || !formData.email || !formData.phone) {
      addToast({ type: 'error', title: 'Validation Error', message: 'Please complete all required fields.' });
      return;
    }

    try {
      registerStaff({
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        phone: formData.phone,
        role: formData.role,
        departmentId: 'dept_001', // default assigned department
        qualification: formData.qualification,
        salary: Number(formData.salary),
        bankAccount: formData.bankName ? {
          bankName: formData.bankName,
          accountName: formData.accountName,
          accountNumber: formData.accountNumber,
        } : undefined
      });

      addToast({
        type: 'success',
        title: 'Staff Registered',
        message: `${formData.firstName} ${formData.lastName} has been successfully registered.`
      });

      navigate('/staff');
    } catch (err) {
      addToast({
        type: 'error',
        title: 'Registration Failed',
        message: 'Could not register staff member. Please try again.'
      });
    }
  };

  return (
    <PageWrapper
      title="Staff Registration"
      subtitle="Register a new academic teacher or auxiliary team member into the school registry."
      breadcrumbs={[
        { label: 'Dashboard', path: '/dashboard' },
        { label: 'Staff', path: '/staff' },
        { label: 'Register Staff' },
      ]}
    >
      <div className="max-w-3xl mx-auto">
        <form onSubmit={handleSubmit}>
          <Card>
            <CardBody className="space-y-6">
              <div className="border-b border-slate-100 dark:border-slate-800 pb-3 flex items-center gap-2">
                <UserPlus className="h-5 w-5 text-primary-600" />
                <h3 className="text-base font-bold font-heading text-slate-900 dark:text-white">Personal Credentials</h3>
              </div>

              <div className="grid grid-2 gap-4">
                <Input
                  label="First Name *"
                  value={formData.firstName}
                  onChange={(e) => handleInputChange('firstName', e.target.value)}
                />
                <Input
                  label="Last Name *"
                  value={formData.lastName}
                  onChange={(e) => handleInputChange('lastName', e.target.value)}
                />
              </div>

              <div className="grid grid-2 gap-4">
                <Input
                  label="Email *"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                />
                <Input
                  label="Phone *"
                  value={formData.phone}
                  onChange={(e) => handleInputChange('phone', e.target.value)}
                />
              </div>

              <div className="border-b border-slate-100 dark:border-slate-800 pb-3 pt-4 flex items-center gap-2">
                <UserPlus className="h-5 w-5 text-primary-600" />
                <h3 className="text-base font-bold font-heading text-slate-900 dark:text-white">Employment & Financials</h3>
              </div>

              <div className="grid grid-3 gap-4">
                <Select
                  label="Staff Role *"
                  value={formData.role}
                  onChange={(e) => handleInputChange('role', e.target.value)}
                  placeholder="Select Staff Role"
                  options={[
                    { value: 'teacher', label: 'Teacher' },
                    { value: 'head_teacher', label: 'Head Teacher' },
                    { value: 'accountant', label: 'Accountant' },
                    { value: 'secretary', label: 'Secretary' },
                    { value: 'librarian', label: 'Librarian' },
                    { value: 'security', label: 'Security' },
                    { value: 'cleaner', label: 'Cleaner' },
                  ]}
                />
                <Input
                  label="Basic Monthly Salary *"
                  type="number"
                  value={formData.salary}
                  onChange={(e) => handleInputChange('salary', Number(e.target.value))}
                />
                <Input
                  label="Qualification"
                  placeholder="e.g. B.Ed, M.Sc"
                  value={formData.qualification}
                  onChange={(e) => handleInputChange('qualification', e.target.value)}
                />
              </div>

              {/* Bank Details */}
              <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                <h4 className="text-sm font-bold uppercase tracking-wider text-slate-400">Salary Bank Credentials (Optional)</h4>
                <div className="grid grid-3 gap-4">
                  <Input
                    label="Bank Name"
                    value={formData.bankName}
                    onChange={(e) => handleInputChange('bankName', e.target.value)}
                  />
                  <Input
                    label="Account Name"
                    value={formData.accountName}
                    onChange={(e) => handleInputChange('accountName', e.target.value)}
                  />
                  <Input
                    label="Account Number"
                    value={formData.accountNumber}
                    onChange={(e) => handleInputChange('accountNumber', e.target.value)}
                  />
                </div>
              </div>
            </CardBody>

            <CardFooter className="flex justify-between">
              <Button type="button" variant="outline" onClick={() => navigate('/staff')}>
                <ArrowLeft className="h-4 w-4 mr-1.5" /> Cancel
              </Button>
              <Button type="submit" variant="primary" className="bg-success-600 hover:bg-success-700 text-white shadow-success">
                <Save className="h-4 w-4 mr-1.5" /> Save Staff Record
              </Button>
            </CardFooter>
          </Card>
        </form>
      </div>
    </PageWrapper>
  );
}

import { useState, useMemo } from 'react';
import { useStudents } from '../hooks/useStudents';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Badge } from '../../../components/ui/Badge';
import { Select } from '../../../components/ui/Select';
import { Input } from '../../../components/ui/Input';
import { DataTable, Column } from '../../../components/data-display/DataTable';
import { Student, AdmissionStatus } from '../../../types';
import { Check, X, UserPlus } from 'lucide-react';
import { useNotificationStore } from '../../../stores/notificationStore';

export default function AdmissionsPage() {
  const { students, updateAdmissionStatus } = useStudents();
  const addToast = useNotificationStore(state => state.addToast);

  const [searchQuery, setSearchQuery] = useState('');
  const [pipelineFilter, setPipelineFilter] = useState<AdmissionStatus | 'all'>('all');

  // Filter for students who are in the admissions process (applied, under_review, accepted, rejected)
  const admissionApplications = useMemo(() => {
    const pipelineStatuses = ['applied', 'under_review', 'accepted', 'rejected'];
    return students.filter((s) => {
      const matchesStatus = pipelineFilter === 'all' 
        ? pipelineStatuses.includes(s.status) 
        : s.status === pipelineFilter;

      const matchesSearch = 
        `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
        s.studentId.toLowerCase().includes(searchQuery.toLowerCase());

      return matchesStatus && matchesSearch;
    });
  }, [students, searchQuery, pipelineFilter]);

  const handleStatusTransition = (id: string, name: string, nextStatus: AdmissionStatus) => {
    try {
      updateAdmissionStatus(id, nextStatus);
      addToast({
        type: 'success',
        title: 'Status Updated',
        message: `${name}'s application status has been changed to ${nextStatus.replace('_', ' ')}.`
      });
    } catch (err) {
      addToast({
        type: 'error',
        title: 'Failed to update status',
        message: 'There was an issue processing the application pipeline change.'
      });
    }
  };

  const columns: Column<Student>[] = [
    {
      header: 'App ID',
      accessorKey: 'studentId',
      sortable: true,
    },
    {
      header: 'Applicant',
      accessorKey: 'firstName',
      sortable: true,
      cell: (item) => (
        <div>
          <p className="font-semibold text-slate-950 dark:text-white">
            {item.firstName} {item.lastName}
          </p>
          <p className="text-xs text-secondary font-light mt-0.5">{item.gender} • {item.classLevel}</p>
        </div>
      ),
    },
    {
      header: 'Guardian Contact',
      accessorKey: 'guardian',
      cell: (item) => (
        <div>
          <p className="text-sm font-medium text-slate-800 dark:text-slate-200">{item.guardian.name}</p>
          <p className="text-xs text-secondary font-light mt-0.5">{item.guardian.phone}</p>
        </div>
      ),
    },
    {
      header: 'Application Status',
      accessorKey: 'status',
      sortable: true,
      cell: (item) => {
        const variant = 
          item.status === 'accepted' ? 'success' :
          item.status === 'under_review' ? 'warning' :
          item.status === 'rejected' ? 'danger' : 'primary';

        return <Badge variant={variant} className="capitalize">{item.status.replace('_', ' ')}</Badge>;
      },
    },
    {
      header: 'Pipeline Action',
      accessorKey: 'actions',
      cell: (item) => {
        const name = `${item.firstName} ${item.lastName}`;
        return (
          <div className="flex items-center gap-2">
            {item.status === 'applied' && (
              <Button
                variant="outline"
                size="sm"
                className="py-1 px-2 text-xs"
                onClick={() => handleStatusTransition(item.id, name, 'under_review')}
              >
                Review
              </Button>
            )}

            {item.status === 'under_review' && (
              <div className="flex gap-1.5">
                <Button
                  variant="outline"
                  size="sm"
                  className="bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border-emerald-200 py-1 px-2 text-xs"
                  onClick={() => handleStatusTransition(item.id, name, 'accepted')}
                >
                  <Check className="h-3 w-3 mr-1" /> Accept
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="bg-rose-50 text-rose-700 hover:bg-rose-100 border-rose-200 py-1 px-2 text-xs"
                  onClick={() => handleStatusTransition(item.id, name, 'rejected')}
                >
                  <X className="h-3 w-3 mr-1" /> Reject
                </Button>
              </div>
            )}

            {item.status === 'accepted' && (
              <Button
                variant="primary"
                size="sm"
                className="bg-success-600 hover:bg-success-700 text-white shadow-success py-1 px-2 text-xs"
                onClick={() => handleStatusTransition(item.id, name, 'enrolled')}
              >
                <UserPlus className="h-3 w-3 mr-1" /> Official Enroll
              </Button>
            )}

            {item.status === 'rejected' && (
              <Button
                variant="ghost"
                size="sm"
                className="text-slate-500 py-1 px-2 text-xs"
                onClick={() => handleStatusTransition(item.id, name, 'applied')}
              >
                Re-apply
              </Button>
            )}
          </div>
        );
      },
    },
  ];

  return (
    <PageWrapper
      title="Admissions & Pipelines"
      subtitle="Track, evaluate and process student registration applications from initial application through final enrollment."
      breadcrumbs={[
        { label: 'Dashboard', path: '/dashboard' },
        { label: 'Students', path: '/students' },
        { label: 'Admissions' },
      ]}
    >
      <div className="space-y-6">
        {/* Filters Panel */}
        <Card>
          <CardBody className="grid grid-3 gap-4">
            <Input
              label="Search Applicants"
              placeholder="Search by name, reference..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />

            <Select
              label="Pipeline Stage"
              placeholder="All Application Stages"
              value={pipelineFilter}
              onChange={(e) => setPipelineFilter(e.target.value as any)}
              options={[
                { value: 'applied', label: 'Applied' },
                { value: 'under_review', label: 'Under Review' },
                { value: 'accepted', label: 'Accepted' },
                { value: 'rejected', label: 'Rejected' },
              ]}
            />
          </CardBody>
        </Card>

        {/* Pipeline DataTable */}
        <Card>
          <CardBody className="p-0">
            <DataTable
              data={admissionApplications}
              columns={columns}
              pageSize={10}
            />
          </CardBody>
        </Card>
      </div>
    </PageWrapper>
  );
}

import { useState } from 'react';
import { useStudents } from '../hooks/useStudents';
import { PageWrapper } from '../../../components/layout/PageWrapper';
import { Card, CardBody, CardFooter } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Textarea } from '../../../components/ui/Textarea';
import { useNotificationStore } from '../../../stores/notificationStore';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, ArrowRight, Save, UserPlus } from 'lucide-react';
import { ClassLevel } from '../../../types';

export default function EnrollPage() {
  const navigate = useNavigate();
  const { enrollStudent } = useStudents();
  const addToast = useNotificationStore(state => state.addToast);

  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    middleName: '',
    dateOfBirth: '',
    gender: 'Female' as 'Female' | 'Male',
    classLevel: 'JHS 1',
    address: '',
    previousSchool: '',
    healthInfo: '',
    guardianName: '',
    guardianRelationship: 'Father',
    guardianPhone: '',
    guardianEmail: '',
    guardianAddress: '',
  });

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const nextStep = () => {
    // Basic validations
    if (step === 1) {
      if (!formData.firstName || !formData.lastName || !formData.dateOfBirth) {
        addToast({ type: 'error', title: 'Validation Error', message: 'Please complete all required personal details.' });
        return;
      }
    } else if (step === 2) {
      if (!formData.guardianName || !formData.guardianPhone || !formData.guardianAddress) {
        addToast({ type: 'error', title: 'Validation Error', message: 'Please complete all required guardian details.' });
        return;
      }
    }
    setStep(prev => prev + 1);
  };

  const prevStep = () => {
    setStep(prev => prev - 1);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    try {
      enrollStudent({
        firstName: formData.firstName,
        lastName: formData.lastName,
        middleName: formData.middleName,
        dateOfBirth: formData.dateOfBirth,
        gender: formData.gender,
        classLevel: formData.classLevel as ClassLevel,
        address: formData.address,
        previousSchool: formData.previousSchool,
        healthInfo: formData.healthInfo,
        guardian: {
          name: formData.guardianName,
          relationship: formData.guardianRelationship,
          phone: formData.guardianPhone,
          email: formData.guardianEmail,
          address: formData.guardianAddress,
        }
      });

      addToast({
        type: 'success',
        title: 'Enrollment Successful',
        message: `${formData.firstName} ${formData.lastName} has been enrolled in ${formData.classLevel}.`
      });

      navigate('/students');
    } catch (err) {
      addToast({
        type: 'error',
        title: 'Enrollment Failed',
        message: 'Could not save student data. Please try again.'
      });
    }
  };

  return (
    <PageWrapper
      title="Student Admission Wizard"
      subtitle="Complete the multi-step workflow to register and enroll a new student into classes."
      breadcrumbs={[
        { label: 'Dashboard', path: '/dashboard' },
        { label: 'Students', path: '/students' },
        { label: 'New Admission' },
      ]}
    >
      <div className="max-w-3xl mx-auto space-y-6">
        {/* Progress Timeline Header */}
        <div className="flex justify-between items-center px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl">
          {[
            { step: 1, label: 'Bio Details' },
            { step: 2, label: 'Guardian' },
            { step: 3, label: 'Academic & Review' },
          ].map((item) => (
            <div key={item.step} className="flex items-center gap-2">
              <div
                className={`w-7 h-7 rounded-full flex-center font-bold text-xs shrink-0 select-none ${
                  step === item.step
                    ? 'bg-primary-600 text-white shadow-primary'
                    : step > item.step
                    ? 'bg-emerald-500 text-white'
                    : 'bg-slate-100 dark:bg-slate-800 text-slate-400'
                }`}
              >
                {item.step}
              </div>
              <span className={`text-xs font-semibold hidden sm:inline ${step === item.step ? 'text-primary-600' : 'text-secondary'}`}>
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Wizard Form Cards */}
        <form onSubmit={handleSubmit}>
          <Card>
            <CardBody className="space-y-6">
              {/* STEP 1: Personal/Bio Details */}
              {step === 1 && (
                <div className="space-y-4">
                  <div className="border-b border-slate-100 dark:border-slate-800 pb-3 flex items-center gap-2">
                    <UserPlus className="h-5 w-5 text-primary-600" />
                    <h3 className="text-base font-bold font-heading text-slate-900 dark:text-white">Student Personal Details</h3>
                  </div>

                  <div className="grid grid-2 gap-4">
                    <Input
                      label="First Name *"
                      value={formData.firstName}
                      onChange={(e) => handleInputChange('firstName', e.target.value)}
                    />
                    <Input
                      label="Last Name *"
                      value={formData.lastName}
                      onChange={(e) => handleInputChange('lastName', e.target.value)}
                    />
                  </div>

                  <div className="grid grid-3 gap-4">
                    <Input
                      label="Middle Name"
                      value={formData.middleName}
                      onChange={(e) => handleInputChange('middleName', e.target.value)}
                    />
                    <Input
                      label="Date of Birth *"
                      type="date"
                      value={formData.dateOfBirth}
                      onChange={(e) => handleInputChange('dateOfBirth', e.target.value)}
                    />
                    <Select
                      label="Gender *"
                      value={formData.gender}
                      onChange={(e) => handleInputChange('gender', e.target.value as any)}
                      placeholder="Select Gender"
                      options={[
                        { value: 'Female', label: 'Female' },
                        { value: 'Male', label: 'Male' },
                      ]}
                    />
                  </div>

                  <Textarea
                    label="Home Address"
                    value={formData.address}
                    onChange={(e) => handleInputChange('address', e.target.value)}
                  />
                </div>
              )}

              {/* STEP 2: Guardian Details */}
              {step === 2 && (
                <div className="space-y-4">
                  <div className="border-b border-slate-100 dark:border-slate-800 pb-3 flex items-center gap-2">
                    <UserPlus className="h-5 w-5 text-primary-600" />
                    <h3 className="text-base font-bold font-heading text-slate-900 dark:text-white">Guardian Information</h3>
                  </div>

                  <div className="grid grid-2 gap-4">
                    <Input
                      label="Guardian Name *"
                      value={formData.guardianName}
                      onChange={(e) => handleInputChange('guardianName', e.target.value)}
                    />
                    <Select
                      label="Relationship *"
                      value={formData.guardianRelationship}
                      onChange={(e) => handleInputChange('guardianRelationship', e.target.value)}
                      placeholder="Select Relationship"
                      options={[
                        { value: 'Father', label: 'Father' },
                        { value: 'Mother', label: 'Mother' },
                        { value: 'Uncle', label: 'Uncle' },
                        { value: 'Aunt', label: 'Aunt' },
                        { value: 'Guardian', label: 'Other Guardian' },
                      ]}
                    />
                  </div>

                  <div className="grid grid-2 gap-4">
                    <Input
                      label="Guardian Phone *"
                      value={formData.guardianPhone}
                      onChange={(e) => handleInputChange('guardianPhone', e.target.value)}
                    />
                    <Input
                      label="Guardian Email"
                      type="email"
                      value={formData.guardianEmail}
                      onChange={(e) => handleInputChange('guardianEmail', e.target.value)}
                    />
                  </div>

                  <Textarea
                    label="Guardian Address *"
                    value={formData.guardianAddress}
                    onChange={(e) => handleInputChange('guardianAddress', e.target.value)}
                  />
                </div>
              )}

              {/* STEP 3: Academic & Review */}
              {step === 3 && (
                <div className="space-y-6">
                  <div className="space-y-4">
                    <div className="border-b border-slate-100 dark:border-slate-800 pb-3 flex items-center gap-2">
                      <UserPlus className="h-5 w-5 text-primary-600" />
                      <h3 className="text-base font-bold font-heading text-slate-900 dark:text-white">Academic Details</h3>
                    </div>

                    <div className="grid grid-2 gap-4">
                      <Select
                        label="Assign Class Level *"
                        value={formData.classLevel}
                        onChange={(e) => handleInputChange('classLevel', e.target.value)}
                        placeholder="Select Class Level"
                        options={[
                          { value: 'JHS 1', label: 'JHS 1' },
                          { value: 'JHS 2', label: 'JHS 2' },
                          { value: 'JHS 3', label: 'JHS 3' },
                        ]}
                      />
                      <Input
                        label="Previous School"
                        value={formData.previousSchool}
                        onChange={(e) => handleInputChange('previousSchool', e.target.value)}
                      />
                    </div>

                    <Textarea
                      label="Medical/Health Information Notes"
                      placeholder="Note allergies, medical conditions, etc."
                      value={formData.healthInfo}
                      onChange={(e) => handleInputChange('healthInfo', e.target.value)}
                    />
                  </div>

                  {/* Summary Review Block */}
                  <div className="space-y-4 border-t border-slate-100 dark:border-slate-800 pt-6">
                    <h4 className="text-sm font-bold uppercase tracking-wider text-slate-400">Review Summary Info</h4>

                    <div className="grid grid-2 gap-4 p-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/10">
                      <div>
                        <p className="text-xs text-slate-400 font-light">Student Name:</p>
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{formData.firstName} {formData.lastName}</p>
                      </div>
                      <div>
                        <p className="text-xs text-slate-400 font-light">Assigned Class Level:</p>
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{formData.classLevel}</p>
                      </div>
                      <div>
                        <p className="text-xs text-slate-400 font-light">Guardian Name:</p>
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{formData.guardianName} ({formData.guardianRelationship})</p>
                      </div>
                      <div>
                        <p className="text-xs text-slate-400 font-light">Guardian Contact:</p>
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{formData.guardianPhone}</p>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </CardBody>

            <CardFooter className="flex justify-between">
              <Button
                type="button"
                variant="outline"
                onClick={step === 1 ? () => navigate('/students') : prevStep}
              >
                <ArrowLeft className="h-4 w-4 mr-1.5" />
                {step === 1 ? 'Cancel' : 'Back'}
              </Button>

              {step < 3 ? (
                <Button type="button" variant="primary" onClick={nextStep}>
                  Next
                  <ArrowRight className="h-4 w-4 ml-1.5" />
                </Button>
              ) : (
                <Button type="submit" variant="primary" className="bg-success-600 hover:bg-success-700 text-white shadow-success">
                  <Save className="h-4 w-4 mr-1.5" />
                  Save & Enroll
                </Button>
              )}
            </CardFooter>
          </Card>
        </form>
      </div>
    </PageWrapper>
  );
}
